-- Compliance system-template catalog.
--
-- Gap closed (H4): compliance checklist templates have no system-level
-- source of truth — they live per-org in `compliance_checklist_templates`,
-- and historically accreted via one-off seed-migration batches that backfilled
-- existing orgs only. `provision_compliance_baseline_for_org` reproduced just
-- 13 of the 37 `is_system` aml-amu templates, so every NEW organization
-- received an incomplete internkontroll baseline (IK-forskriften § 5).
--
-- Fix: introduce `compliance_system_templates`, a true system catalog (same
-- role as survey_template_catalog / document_system_templates), seeded with
-- every distinct system template across all packs (37 aml-amu + 7 iso-9001 +
-- 1 iso-45001 = 45). `provision_compliance_baseline_for_org` is rewritten to
-- copy from the catalog, and `compliance_pack_provision_on_change` now creates
-- the checklist categories BEFORE provisioning so each template's category_id
-- resolves. Existing orgs are re-provisioned idempotently (on conflict do
-- nothing) so they converge without disturbing customised rows.
--
-- Self-audit (Arbeidstilsynet POV): pålegg-grunn addressed — a new virksomhet
-- now receives the full systematic-HMS checklist set instead of a 13-template
-- subset. Restrisiko deferred: iso-14001 / iso-27001 have no system templates
-- yet (ISO 27001 is seeded by studio_iso27001_seed); compliance_template_
-- requirements linkage is not catalogued (it already produced nothing for
-- fresh orgs under the old function).

create table if not exists public.compliance_system_templates (
  id uuid primary key default gen_random_uuid(),
  pack public.compliance_pack not null,
  slug text not null,
  name text not null,
  description text,
  definition jsonb not null default '{"items": []}'::jsonb,
  nav_pinned boolean not null default false,
  cadence_hint text,
  metadata_schema jsonb not null default '{"fields": []}'::jsonb,
  law_refs text[] not null default '{}'::text[],
  review_status public.compliance_review_status not null default 'draft',
  category_slug text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (pack, slug)
);

comment on table public.compliance_system_templates is
  'System-wide catalog of compliance checklist templates. provision_compliance_baseline_for_org copies these into per-org compliance_checklist_templates. category_slug resolves to a per-org compliance_checklist_categories row.';

alter table public.compliance_system_templates enable row level security;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname='public' and tablename='compliance_system_templates'
      and policyname='compliance_system_templates_read'
  ) then
    create policy compliance_system_templates_read
      on public.compliance_system_templates
      for select to authenticated using (true);
  end if;
end$$;

