insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'amu-arsrapport-sjekk', 'AMU-møte – protokoll og sjekk', 'Sjekkliste per AMU-møte: protokoll, agenda og lovpålagte sakstyper (AML §7-1, §7-2, §7-4). Kun for virksomheter med 50 eller flere ansatte. Minst 4 møter per år.',
  '{"items": [{"key": "mote_avholdt", "type": "yes_no_na", "prompt": "Er AMU-møtet avholdt (minst 4 møter per kalenderår)?", "law_ref": "AML §7-1", "required": true, "severity_default": "critical"}, {"key": "mote_dato", "type": "date", "prompt": "Dato for dette AMU-møtet", "law_ref": "AML §7-2", "required": true}, {"key": "protokoll_fort", "help": "Protokollen er offentlig og skal oppbevares. AMU kan kreve den lagt frem for Arbeidstilsynet.", "type": "yes_no_na", "prompt": "Er møteprotokoll ført og undertegnet av AMU-leder og sekretær?", "law_ref": "AML §7-4", "required": true, "severity_default": "critical"}, {"key": "aarsplan_behandlet", "type": "yes_no_na", "prompt": "Er årsplan og HMS-årsrapport behandlet?", "law_ref": "AML §7-2", "required": true, "severity_default": "high"}, {"key": "skaderegister_gjennomgatt", "type": "yes_no_na", "prompt": "Er skade- og sykdomsregisteret gjennomgått og presentert?", "law_ref": "AML §7-2", "required": true, "severity_default": "high"}, {"key": "avvik_handlingsplan", "type": "yes_no_na", "prompt": "Er åpne avvik og handlingsplan gjennomgått?", "required": true, "severity_default": "medium"}, {"key": "bht_rapport", "help": "Gjelder for BHT-pliktige virksomheter.", "type": "yes_no_na", "prompt": "Er BHTs årsrapport og plan behandlet?", "law_ref": "AML §3-3", "required": false, "severity_default": "medium"}, {"key": "verneombud_rapport", "type": "yes_no_na", "prompt": "Har verneombudet rapportert sine observasjoner til AMU?", "law_ref": "AML §6-2", "required": false, "severity_default": "medium"}, {"key": "drofting_vesentlige_saker", "help": "Virksomheter med minst 50 ansatte har informasjons- og drøftingsplikt etter §8-1.", "type": "yes_no_na", "prompt": "Er vesentlige saker for arbeids- og ansettelsesvilkår informert om og drøftet?", "law_ref": "AML §8-1", "required": false, "severity_default": "medium"}, {"key": "protokoll_distribuert", "type": "yes_no_na", "prompt": "Er protokollen distribuert til alle AMU-representanter innen rimelig tid?", "required": true, "severity_default": "high"}, {"key": "neste_mote_dato", "type": "date", "prompt": "Dato for neste AMU-møte", "required": false}, {"key": "signatur_amu_leder", "type": "signature", "prompt": "AMU-leders signatur", "law_ref": "AML §7-4", "required": true}, {"key": "signatur_verneombud", "type": "signature", "prompt": "Verneombudets signatur", "law_ref": "AML §6-2", "required": true}]}'::jsonb,
  false, 'kvartalsvis (hvert AMU-møte)',
