  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'apenhetsloven-arsgjennomgang', 'Åpenhetsloven — årsgjennomgang og redegjørelse', 'Årlig kontroll av åpenhetslov-pliktene: aktsomhetsvurderinger av egen virksomhet + leverandørkjeden, oppdatert redegjørelse innen 30. juni, og rutiner for informasjonskrav fra offentligheten.',
  '{"items": [{"key": "virkeomraadeavklart", "help": "§ 3 definerer \"større virksomheter\" — over 50 ansatte, eller over visse omsetningsterskler.", "type": "yes_no_na", "prompt": "Er det skriftlig avklart at virksomheten faller inn under åpenhetslovens virkeområde?", "law_ref": "Åpenhetsloven § 3", "required": true, "severity_default": "high"}, {"key": "aktsomhet_egen", "type": "yes_no_na", "prompt": "Er det utført aktsomhetsvurdering av risiko for negative konsekvenser i egen virksomhet?", "law_ref": "Åpenhetsloven § 4", "required": true, "severity_default": "critical"}, {"key": "aktsomhet_leverandor", "help": "OECDs retningslinjer + ILOs kjernekonvensjoner skal være referansegrunnlag.", "type": "yes_no_na", "prompt": "Er det utført aktsomhetsvurdering av leverandørkjede og forretningsforbindelser?", "law_ref": "Åpenhetsloven § 4", "required": true, "severity_default": "critical"}, {"key": "tiltak_lukket", "type": "yes_no_na", "prompt": "Er identifiserte negative konsekvenser fulgt opp med konkrete tiltak (stansing, forebygging, gjenoppretting)?", "law_ref": "Åpenhetsloven § 4", "required": true, "severity_default": "high"}, {"key": "redegjorelse", "help": "§ 5 krever redegjørelse på virksomhetens nettside, lett tilgjengelig.", "type": "yes_no_na", "prompt": "Er årlig redegjørelse offentliggjort innen 30. juni, signert av styret / øverste ledelse?", "law_ref": "Åpenhetsloven § 5", "required": true, "severity_default": "critical"}, {"key": "informasjonskrav_rutine", "type": "yes_no_na", "prompt": "Har virksomheten en rutine for å svare på informasjonskrav fra offentligheten innen tre uker?", "law_ref": "Åpenhetsloven § 6", "required": true, "severity_default": "high"}, {"key": "informasjonskrav_logg", "type": "yes_no_na", "prompt": "Føres det logg over mottatte informasjonskrav og svartider siste 12 mnd.?", "law_ref": "Åpenhetsloven § 7", "required": false, "severity_default": "medium"}, {"key": "tilsyn_kjent", "type": "yes_no_na", "prompt": "Er ledelsen kjent med at Forbrukertilsynet fører tilsyn og kan ilegge tvangsmulkt?", "law_ref": "Åpenhetsloven § 8", "required": false, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / forbedringspunkter", "required": false}, {"key": "sign_apenhet", "type": "signature", "prompt": "Åpenhetslov-ansvarliges signatur", "required": true}, {"key": "sign_dl", "type": "signature", "prompt": "Daglig leders signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['Åpenhetsloven § 3', 'Åpenhetsloven § 4', 'Åpenhetsloven § 5', 'Åpenhetsloven § 6', 'Åpenhetsloven § 7', 'Åpenhetsloven § 8']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'arbeidsavtale-sjekk', 'Arbeidsavtale-sjekk', 'Kontroll av at den skriftlige arbeidsavtalen oppfyller minstekrav før signering (AML §14-5 + §14-6).',
  '{"items": [{"key": "partenes_identitet", "type": "yes_no_na", "prompt": "Er partenes identitet angitt?", "law_ref": "AML §14-6 (1) a", "required": true}, {"key": "arbeidssted", "type": "yes_no_na", "prompt": "Er arbeidssted angitt?", "law_ref": "AML §14-6 (1) b", "required": true}, {"key": "stillingsbetegnelse", "type": "yes_no_na", "prompt": "Er stillingsbetegnelse / arbeidsoppgaver beskrevet?", "law_ref": "AML §14-6 (1) c", "required": true}, {"key": "tiltredelse_dato", "type": "yes_no_na", "prompt": "Er tiltredelsesdato angitt?", "law_ref": "AML §14-6 (1) d", "required": true}, {"key": "varighet", "type": "yes_no_na", "prompt": "Er varighet (fast / midlertidig) angitt?", "law_ref": "AML §14-6 (1) e", "required": true}, {"key": "proevetid", "type": "yes_no_na", "prompt": "Er prøvetid (om aktuelt) skriftlig avtalt?", "law_ref": "AML §14-6 (1) f", "required": false, "severity_default": "medium"}, {"key": "ferierettigheter", "type": "yes_no_na", "prompt": "Er rett til ferie og feriepenger angitt?", "law_ref": "AML §14-6 (1) g", "required": true}, {"key": "oppsigelsesfrister", "type": "yes_no_na", "prompt": "Er oppsigelsesfrister angitt?", "law_ref": "AML §14-6 (1) h", "required": true}, {"key": "lonn", "type": "yes_no_na", "prompt": "Er lønn / godtgjørelse spesifisert?", "law_ref": "AML §14-6 (1) i", "required": true}, {"key": "arbeidstid", "type": "yes_no_na", "prompt": "Er arbeidstid (lengde + plassering) angitt?", "law_ref": "AML §14-6 (1) j", "required": true}, {"key": "pauser", "type": "yes_no_na", "prompt": "Er rett til pauser angitt?", "law_ref": "AML §14-6 (1) k", "required": true}, {"key": "tariffavtale", "type": "yes_no_na", "prompt": "Er eventuell tariffavtale angitt?", "law_ref": "AML §14-6 (1) l", "required": false, "severity_default": "low"}, {"key": "signatur_arbeidsgiver", "type": "signature", "prompt": "Arbeidsgivers signatur", "law_ref": "AML §14-5", "required": true}, {"key": "signatur_ansatt", "type": "signature", "prompt": "Den ansattes signatur", "law_ref": "AML §14-5", "required": true}]}'::jsonb,
  true, 'ved tilsetting',
  '{"fields": []}'::jsonb,
  array['AML § 14-5', 'AML § 14-6', 'AML § 14-9']::text[],
  'draft', 'ansettelse'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
