insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'arbeidstid-kontroll', 'Arbeidstid – periodisk kontroll', 'Kvartalsvis kontroll av at arbeidstidsregler overholdes: ordinær tid, hvile, pauser, overtid og søn-/nattarbeid (AML kap. 10). Supplerer timerapporter.',
  '{"items": [{"key": "periode", "type": "text", "prompt": "Hvilken periode kontrolleres? (dd.mm.åååå – dd.mm.åååå)", "required": true}, {"key": "daglig_arbeidstid_ok", "type": "yes_no_na", "prompt": "Overholdes grensen på maks 9 timer daglig og 40 timer ukentlig ordinær arbeidstid?", "law_ref": "AML §10-4", "required": true, "severity_default": "critical"}, {"key": "daglig_hvile_11t", "help": "Unntak kan avtales med tillitsvalgte, men gir krav på kompenserende hvile.", "type": "yes_no_na", "prompt": "Overholdes kravet om minst 11 timers sammenhengende hvile per 24-timersperiode?", "law_ref": "AML §10-8", "required": true, "severity_default": "critical"}, {"key": "ukentlig_hvile_35t", "type": "yes_no_na", "prompt": "Overholdes kravet om minst 35 timers ukentlig hvile?", "law_ref": "AML §10-8", "required": true, "severity_default": "high"}, {"key": "pauser_sikret", "type": "yes_no_na", "prompt": "Er ansatte sikret rett til pause på minst 30 min ved arbeidsdag over 5,5 timer?", "law_ref": "AML §10-9", "required": true, "severity_default": "medium"}, {"key": "overtid_grenser_ok", "type": "yes_no_na", "prompt": "Overholdes overtidsgrensene: maks 10t/uke, 25t/4 uker, 200t/år?", "law_ref": "AML §10-6", "required": true, "severity_default": "critical"}, {"key": "overtid_droftet", "help": "Gjelder for virksomheter med tariffavtale eller tillitsvalgte.", "type": "yes_no_na", "prompt": "Er bruk av overtid drøftet med tillitsvalgte der det er aktuelt?", "law_ref": "AML §10-6", "required": false, "severity_default": "medium"}, {"key": "arbeidstid_oversikt", "help": "Plikten gjelder alle arbeidsgivere. Oversikten skal være tilgjengelig for Arbeidstilsynet.", "type": "yes_no_na", "prompt": "Føres det løpende oversikt over de ansattes arbeidstid?", "law_ref": "AML §10-7", "required": true, "severity_default": "high"}, {"key": "sondagsarbeid_regulert", "help": "Kun aktuelt for virksomheter med søndagsarbeid.", "type": "yes_no_na", "prompt": "Er søn- og helgedagsarbeid regulert eller godkjent per avtale/unntak?", "law_ref": "AML §10-10", "required": false, "severity_default": "medium"}, {"key": "nattarbeid_regulert", "help": "Kun aktuelt for virksomheter med nattarbeid.", "type": "yes_no_na", "prompt": "Er nattarbeid (kl. 21–06) regulert per unntak eller tariffavtale?", "law_ref": "AML §10-11", "required": false, "severity_default": "medium"}, {"key": "antall_overtidstimer", "type": "number", "prompt": "Totalt antall overtidstimer i perioden (alle ansatte samlet)", "required": false}, {"key": "avvik_og_tiltak", "type": "text", "prompt": "Identifiserte avvik og planlagte tiltak", "required": false}, {"key": "signatur", "type": "signature", "prompt": "HMS-/HR-ansvarlig signatur", "law_ref": "AML §10-7", "required": true}]}'::jsonb,
  false, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 10-4', 'AML § 10-6', 'AML § 10-7', 'AML § 10-8', 'AML § 10-10', 'AML § 10-11', 'AML § 10-12']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'arbeidstid-kvartalsgjennomgang', 'Arbeidstid — kvartalsvis gjennomgang', 'Kvartalsvis kontroll av at arbeidstidsregistreringen er fullstendig, at hvile- og overtidsregler overholdes, og at unntakslister etter § 10-12 er korrekte. Leverer dokumentasjon ved tilsyn.',
  '{"items": [{"key": "oversikt_komplett", "type": "yes_no_na", "prompt": "Er § 10-7-oversikten oppdatert og tilgjengelig for alle ansatte og innleide?", "law_ref": "AML § 10-7", "required": true, "severity_default": "critical"}, {"key": "manglende_reg", "type": "number", "prompt": "Hvor mange ansatte har manglende eller ufullstendig registrering siste 13 uker?", "law_ref": "AML § 10-7", "required": true, "severity_default": "high"}, {"key": "daglig_hvile", "help": "Brudd skal være meldt som avvik og ha skriftlig tillitsvalgt-avtale hvis tilbakevendende.", "type": "yes_no_na", "prompt": "Er det avdekket brudd på 11-timers daglig hvile siste 13 uker?", "law_ref": "AML § 10-8 (1)", "required": true, "severity_default": "critical"}, {"key": "ukentlig_hvile", "type": "yes_no_na", "prompt": "Er det avdekket brudd på 35-timers ukentlig hvile siste 13 uker?", "law_ref": "AML § 10-8 (2)", "required": true, "severity_default": "critical"}, {"key": "overtid_uke", "type": "yes_no_na", "prompt": "Er noen ansatte over 10t overtid pr. uke uten dispensasjon eller avtale?", "law_ref": "AML § 10-6", "required": true, "severity_default": "critical"}, {"key": "overtid_aar", "type": "yes_no_na", "prompt": "Er noen ansatte over 200t overtid på rullerende 52 uker uten utvidet avtale?", "law_ref": "AML § 10-6 (4)", "required": true, "severity_default": "high"}, {"key": "overtidskompensasjon", "type": "yes_no_na", "prompt": "Er overtid kompensert med minst 40 % tillegg eller avtalt avspasering?", "law_ref": "AML § 10-6 (11)", "required": true, "severity_default": "high"}, {"key": "soenarb", "type": "yes_no_na", "prompt": "Er søndags-/helgedagsarbeid begrunnet i arbeidets art eller forhåndsavtalt?", "law_ref": "AML § 10-10", "required": true, "severity_default": "high"}, {"key": "natt_helsekontroll", "type": "yes_no_na", "prompt": "Har nattarbeidere fått tilbud om helsekontroll?", "law_ref": "AML § 10-11 (7)", "required": false, "severity_default": "high"}, {"key": "unntak_liste", "help": "Tilsynet ser særlig på misbruk av «særlig uavhengig stilling».", "type": "yes_no_na", "prompt": "Er liste over stillinger unntatt etter § 10-12 oppdatert og drøftet med tillitsvalgte?", "law_ref": "AML § 10-12", "required": true, "severity_default": "high"}, {"key": "vaktordninger_avtale", "type": "yes_no_na", "prompt": "Er gjennomsnittsberegninger / særavtaler etter § 10-5 gyldig protokollført?", "law_ref": "AML § 10-5", "required": false, "severity_default": "high"}, {"key": "avvik_oppfolging", "type": "yes_no_na", "prompt": "Er meldte arbeidstidsavvik fulgt opp og lukket innen 60 dager?", "law_ref": "IK-f § 5 nr. 7", "required": true, "severity_default": "medium"}, {"key": "amu_orientert", "type": "yes_no_na", "prompt": "Er statistikken lagt fram for AMU?", "law_ref": "AML § 7-2", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner", "required": false}, {"key": "sign_hr", "type": "signature", "prompt": "HR-/personalansvarliges signatur", "required": true}, {"key": "sign_vo", "type": "signature", "prompt": "Verneombudets signatur", "required": true}]}'::jsonb,
  false, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 10-4', 'AML § 10-6', 'AML § 10-7', 'AML § 10-8', 'AML § 10-10', 'AML § 10-11', 'AML § 10-12']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'avviksoppfolging-runde', 'Avviksoppfølging-runde', 'Kvartalsvis gjennomgang av åpne avvik, forebyggende tiltak og effekt av lukkede saker (IK-forskriften §5 nr. 7).',
  '{"items": [{"key": "aapne_avvik_oversikt", "type": "yes_no_na", "prompt": "Er status for åpne avvik gjennomgått siste kvartal?", "law_ref": "IK-forskriften §5 nr. 7", "required": true, "severity_default": "high"}, {"key": "forebygge_gjentakelse", "type": "text", "prompt": "Hvilke tiltak er iverksatt for å forebygge gjentakelse?", "law_ref": "IK-forskriften §5 nr. 7", "required": true}, {"key": "lukket_avvik_eff", "type": "yes_no_na", "prompt": "Er effekt av lukkede avvik verifisert?", "law_ref": "IK-forskriften §5 nr. 7", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Kommentar / observasjoner", "required": false}, {"key": "signatur_hms_leder", "type": "signature", "prompt": "HMS-leders signatur", "required": true}]}'::jsonb,
  true, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 5-1', 'IK-f § 5 nr. 7']::text[],
  'draft', 'internkontroll'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
