  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'bht-arsplan-gjennomgang', 'BHT — årlig samarbeidsgjennomgang', 'Årlig kontroll av at avtalen med godkjent bedriftshelsetjeneste fungerer i praksis: at samarbeidsplanen er satt opp, gjennomført og evaluert med AMU.',
  '{"items": [{"key": "plikt_avklart", "type": "yes_no_na", "prompt": "Er det avklart om virksomheten er omfattet av BHT-plikten (forskrift § 13-1)?", "law_ref": "Forskrift om org., ledelse og medvirkning § 13-1", "required": true, "severity_default": "high"}, {"key": "avtale_aktiv", "type": "yes_no_na", "prompt": "Foreligger det aktiv avtale med godkjent BHT?", "law_ref": "AML § 3-3", "required": true, "severity_default": "critical"}, {"key": "godkjenning", "type": "yes_no_na", "prompt": "Er BHTs godkjenningsstatus kontrollert i Arbeidstilsynets register?", "law_ref": "AML § 3-3 (3)", "required": true, "severity_default": "high"}, {"key": "samarbeidsplan", "type": "yes_no_na", "prompt": "Er det utarbeidet skriftlig samarbeidsplan for året?", "law_ref": "Forskrift om org., ledelse og medvirkning § 13-2", "required": true, "severity_default": "high"}, {"key": "plan_oppgaver", "type": "yes_no_na", "prompt": "Dekker planen risikokartlegging, helseovervåking, oppfølging av sykmeldte og opplæring?", "law_ref": "§ 13-2", "required": true, "severity_default": "high"}, {"key": "plan_gjennomfort", "type": "yes_no_na", "prompt": "Er aktivitetene i planen gjennomført?", "law_ref": "AML § 3-3", "required": true, "severity_default": "high"}, {"key": "arsrapport", "type": "yes_no_na", "prompt": "Foreligger BHT-rapport for året?", "law_ref": "§ 13-3", "required": true, "severity_default": "high"}, {"key": "amu_behandlet", "type": "yes_no_na", "prompt": "Er BHT-rapporten lagt fram og behandlet i AMU?", "law_ref": "AML § 7-2", "required": true, "severity_default": "high"}, {"key": "helsekontroll", "type": "yes_no_na", "prompt": "Er helsekontroller for eksponerte grupper gjennomført der det kreves?", "law_ref": "AML § 4-5 + § 10-11", "required": false, "severity_default": "high"}, {"key": "sykefravar_oppfolging", "type": "yes_no_na", "prompt": "Bistår BHT i sykefraværsoppfølging?", "law_ref": "AML § 4-6", "required": true, "severity_default": "medium"}, {"key": "tiltak_oppfolging", "type": "yes_no_na", "prompt": "Er forslag til tiltak fra BHT besluttet og fulgt opp?", "law_ref": "AML § 3-1", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner og forbedringspunkter", "required": false}, {"key": "sign_hms", "type": "signature", "prompt": "HMS-leders signatur", "required": true}, {"key": "sign_amu", "type": "signature", "prompt": "AMU-leders signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['AML § 3-3', 'AML § 3-4', 'Forskrift om org., ledelse og medvirkning § 13-1', 'Forskrift om org., ledelse og medvirkning § 13-2']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'bht-samarbeid-arsplan', 'BHT-samarbeid – årsplan og bistand', 'Årlig gjennomgang av samarbeidet med bedriftshelsetjenesten: tilknytning, årsplan, bistandsområder og leveranser (AML §3-3). Deaktiver hvis virksomheten ikke har BHT-plikt.',
  '{"items": [{"key": "bht_tilknyttet", "type": "yes_no_na", "prompt": "Er BHT formelt tilknyttet virksomheten gjennom bistandsavtale?", "law_ref": "AML §3-3", "required": true, "severity_default": "critical"}, {"key": "bht_godkjent", "help": "Sjekk godkjent-bht.no for å verifisere godkjenningstatus.", "type": "yes_no_na", "prompt": "Er BHT godkjent av Arbeidstilsynet?", "law_ref": "AML §3-3", "required": true, "severity_default": "high"}, {"key": "bht_avtale_oppdatert", "type": "yes_no_na", "prompt": "Er bistandsavtalen med BHT oppdatert og dekkende for virksomhetens risikoer?", "law_ref": "AML §3-3", "required": true, "severity_default": "high"}, {"key": "bht_arsplan_mottatt", "type": "yes_no_na", "prompt": "Har BHT levert årsplan for inneværende år?", "required": true, "severity_default": "high"}, {"key": "bht_arsrapport_mottatt", "type": "yes_no_na", "prompt": "Har BHT levert årsrapport for foregående år?", "required": true, "severity_default": "high"}, {"key": "risikovurdering_bistand", "help": "Minimum én kartlegging per år anbefales i risikoeksponerte miljøer.", "type": "yes_no_na", "prompt": "Har BHT bistått med risikovurdering og kartlegging av arbeidsmiljø?", "law_ref": "AML §3-3", "required": true, "severity_default": "medium"}, {"key": "helseundersoekelse", "help": "Påkrevet ved eksponering for støy, kjemikalier, biologiske faktorer, stråling m.m.", "type": "yes_no_na", "prompt": "Er yrkeshelsekontroll gjennomført for eksponerte grupper?", "required": false, "severity_default": "high"}, {"key": "bht_amu", "help": "Gjelder for virksomheter med AMU (≥50 ansatte).", "type": "yes_no_na", "prompt": "Er BHTs årsrapport presentert for AMU?", "law_ref": "AML §7-2", "required": false, "severity_default": "medium"}, {"key": "bht_tilgang", "type": "yes_no_na", "prompt": "Har BHT hatt tilgang til arbeidsplassen og relevante arbeidsprosesser siste år?", "law_ref": "AML §3-3", "required": true, "severity_default": "medium"}, {"key": "fysisk_aktivitet_vurdert", "help": "§3-4: arbeidsgiver skal i tilknytning til systematisk HMS-arbeid vurdere slike tiltak.", "type": "yes_no_na", "prompt": "Er tiltak for å fremme fysisk aktivitet blant ansatte vurdert?", "law_ref": "AML §3-4", "required": false, "severity_default": "low"}, {"key": "neste_bistandsomraader", "type": "text", "prompt": "Planlagte bistandsområder for kommende år (beskriv kort)", "required": false}, {"key": "signatur", "type": "signature", "prompt": "HMS-ansvarlig signatur", "required": true}]}'::jsonb,
  false, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 3-3', 'AML § 3-4']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'brannvernrunde', 'Brannvernrunde', 'Kvartalsvis kontroll av rømningsveier, slokkemidler, branninstruks og samlingsplass (AML §4-4 + Forskrift om brannforebygging).',
  '{"items": [{"key": "roemningsveier_frie", "type": "yes_no_na", "prompt": "Er rømningsveier frie og merkede?", "law_ref": "AML §4-4", "required": true, "severity_default": "critical"}, {"key": "slokkemidler_tilgjengelig", "type": "yes_no_na", "prompt": "Er slokkemidler tilgjengelig og kontrollert?", "law_ref": "AML §4-4", "required": true, "severity_default": "critical"}, {"key": "branninstruks_synlig", "type": "yes_no_na", "prompt": "Er branninstruks tydelig oppslått?", "required": true, "severity_default": "high"}, {"key": "samlingsplass_kjent", "type": "yes_no_na", "prompt": "Vet ansatte hvor samlingsplassen er?", "required": true, "severity_default": "high"}, {"key": "siste_oevelse", "type": "text", "prompt": "Når ble siste branntestøvelse gjennomført? (dd.mm.åååå)", "required": true}, {"key": "foto_avvik", "type": "photo", "prompt": "Bilder av eventuelle avvik", "required": false}, {"key": "signatur", "type": "signature", "prompt": "Verneombudets signatur", "law_ref": "AML §6-2", "required": true}]}'::jsonb,
  true, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 4-4', 'IK-f § 5 nr. 7']::text[],
  'draft', 'fysisk'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'ergonomi-runde', 'Ergonomi-runde', 'Halvårlig vurdering av arbeidsstillinger, tunge løft, gjentakende bevegelser og hjelpemidler (AML §4-4 (2) c).',
  '{"items": [{"key": "arbeidsstilling", "type": "yes_no_na", "prompt": "Er arbeidsstillingen vurdert som forsvarlig?", "law_ref": "AML §4-4 (2) c", "required": true, "severity_default": "medium"}, {"key": "tunge_loft", "type": "yes_no_na", "prompt": "Forekommer tunge løft som ikke er risikovurdert?", "law_ref": "AML §4-4 (2) c", "required": true, "severity_default": "high"}, {"key": "gjentakende_bevegelser", "type": "yes_no_na", "prompt": "Er gjentakende bevegelser identifisert og dempet?", "required": false, "severity_default": "medium"}, {"key": "hjelpemidler_tilgjengelig", "type": "yes_no_na", "prompt": "Er ergonomiske hjelpemidler tilgjengelig der det trengs?", "required": false, "severity_default": "medium"}, {"key": "pauser_tilrettelagt", "type": "yes_no_na", "prompt": "Er pauser og rotering tilstrekkelig?", "required": false, "severity_default": "low"}, {"key": "tiltak_foreslaatt", "type": "text", "prompt": "Forslag til ergonomiske tiltak", "required": false}]}'::jsonb,
  true, 'halvårlig',
  '{"fields": []}'::jsonb,
  array['AML § 4-2', 'AML § 4-4']::text[],
  'draft', 'fysisk'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'gdpr-arsgjennomgang', 'GDPR — årsgjennomgang', 'Årlig kontroll av at virksomhetens behandling av personopplysninger oppfyller GDPR. Dekker behandlingsprotokoll, lovlighet, registrertes rettigheter, sikkerhet, brudd-rutiner og personvernombud.',
  '{"items": [{"key": "prinsipper", "type": "yes_no_na", "prompt": "Er behandlingen i tråd med GDPR-prinsippene (lovlighet, formålsbegrensning, dataminimering, riktighet, lagringsbegrensning, integritet)?", "law_ref": "GDPR Art. 5", "required": true, "severity_default": "critical"}, {"key": "rettsgrunnlag", "type": "yes_no_na", "prompt": "Er rettsgrunnlaget for all behandling av personopplysninger skriftlig dokumentert (samtykke / kontrakt / berettiget interesse / lovkrav / vital interesse)?", "law_ref": "GDPR Art. 6", "required": true, "severity_default": "critical"}, {"key": "informasjonsplikt", "type": "yes_no_na", "prompt": "Får de registrerte tilstrekkelig informasjon om behandlingen ved innsamling (personvernerklæring)?", "law_ref": "GDPR Art. 13", "required": true, "severity_default": "high"}, {"key": "innebygd_personvern", "type": "yes_no_na", "prompt": "Er prinsippene om innebygd og standardinnstilt personvern (data protection by design and by default) hensyntatt ved nye systemer / endringer?", "law_ref": "GDPR Art. 25", "required": true, "severity_default": "high"}, {"key": "protokoll", "help": "Art. 30 krever skriftlig protokoll for behandlinger.", "type": "yes_no_na", "prompt": "Er behandlingsprotokollen (ROPA) oppdatert siste 12 mnd. og dekker alle aktive behandlinger?", "law_ref": "GDPR Art. 30", "required": true, "severity_default": "critical"}, {"key": "sikkerhet", "type": "yes_no_na", "prompt": "Er det iverksatt egnede tekniske og organisatoriske tiltak for å sikre personopplysninger (tilgangsstyring, kryptering, backup, logging)?", "law_ref": "GDPR Art. 32", "required": true, "severity_default": "critical"}, {"key": "brudd_rutine", "type": "yes_no_na", "prompt": "Har virksomheten rutiner for å varsle Datatilsynet om brudd innen 72 timer, og melde registrerte ved høy risiko?", "law_ref": "GDPR Art. 33", "required": true, "severity_default": "critical"}, {"key": "dpia", "type": "yes_no_na", "prompt": "Er det gjennomført personvernkonsekvensvurdering (DPIA) for behandlinger med høy risiko?", "law_ref": "GDPR Art. 35", "required": false, "severity_default": "high"}, {"key": "personvernombud", "type": "yes_no_na", "prompt": "Er personvernombud (DPO) utpekt der dette er krav, og er kontaktinformasjonen kommunisert?", "law_ref": "GDPR Art. 37", "required": false, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / forbedringspunkter", "required": false}, {"key": "sign_dpo", "type": "signature", "prompt": "Personvernombuds / personvernansvarliges signatur", "required": true}, {"key": "sign_dl", "type": "signature", "prompt": "Daglig leders signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['GDPR Art. 5', 'GDPR Art. 6', 'GDPR Art. 13', 'GDPR Art. 25', 'GDPR Art. 30', 'GDPR Art. 32', 'GDPR Art. 33', 'GDPR Art. 35', 'GDPR Art. 37']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'hms-maal-arsplan-sjekk', 'HMS-mål og årsplan – sjekk', 'Sjekkliste for dokumentasjon av HMS-mål og årsplan (IK-forskriften §5 nr. 1 + §5 nr. 4). Gjennomføres ved årsstart / planlegging av HMS-arbeidet for nytt år.',
  '{"items": [{"key": "mal_dokumentert", "type": "yes_no_na", "prompt": "Er HMS-mål for inneværende år skriftlig dokumentert?", "law_ref": "IK-forskriften §5 nr. 4", "required": true, "severity_default": "critical"}, {"key": "mal_konkrete", "type": "yes_no_na", "prompt": "Er målene konkrete, målbare og tidsbestemte?", "required": true, "severity_default": "high"}, {"key": "forrige_aar_evaluert", "type": "yes_no_na", "prompt": "Er fjorårets HMS-mål evaluert og resultat dokumentert?", "law_ref": "IK-forskriften §5 nr. 8", "required": true, "severity_default": "high"}, {"key": "aarsplan_utarbeidet", "type": "yes_no_na", "prompt": "Er årsplan for HMS-aktiviteter utarbeidet?", "law_ref": "IK-forskriften §5 nr. 4", "required": true, "severity_default": "critical"}, {"key": "aarsplan_kommunisert", "type": "yes_no_na", "prompt": "Er årsplan gjort kjent for ansatte og verneombud?", "required": true, "severity_default": "high"}, {"key": "lovkrav_tilgjengelig", "help": "Kan oppfylles ved lenker på intranett, lovdata.no e.l. Ikke krav om fysiske eksemplarer.", "type": "yes_no_na", "prompt": "Er aktuelle lover og forskrifter tilgjengelig og kjent for ansatte?", "law_ref": "IK-forskriften §5 nr. 1", "required": true, "severity_default": "high"}, {"key": "bht_i_plan", "help": "Gjelder for BHT-pliktige virksomheter.", "type": "yes_no_na", "prompt": "Er BHT-bistand planlagt for inneværende år?", "law_ref": "AML §3-3", "required": false, "severity_default": "medium"}, {"key": "vo_inkludert", "type": "yes_no_na", "prompt": "Er verneombudet involvert i årsplanleggingen?", "law_ref": "AML §6-2", "required": true, "severity_default": "medium"}, {"key": "risikovurdering_planlagt", "type": "yes_no_na", "prompt": "Er oppdatering av risikovurderinger planlagt for inneværende år?", "law_ref": "IK-forskriften §5 nr. 6", "required": true, "severity_default": "high"}, {"key": "hms_mal_tekst", "type": "text", "prompt": "Beskriv de viktigste HMS-målene for inneværende år", "law_ref": "IK-forskriften §5 nr. 4", "required": true}, {"key": "signatur_dagligleder", "type": "signature", "prompt": "Daglig leders signatur", "law_ref": "IK-forskriften §5 nr. 4", "required": true}]}'::jsonb,
  true, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 3-1', 'IK-f § 5 nr. 1', 'IK-f § 5 nr. 4', 'IK-f § 5 nr. 6', 'IK-f § 5 nr. 8']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'ia-oppfolgingsplan-sjekk', 'IA-oppfølgingsplan – sjekkliste', 'Sjekkliste ved sykmelding over 4 uker. Sikrer at oppfølgingsplan opprettes, dialogmøter holdes og NAV varsles innen lovens frister (AML §4-6 + IA-avtalen). Én utfylling per sykmeldt ansatt.',
  '{"items": [{"key": "sykmelding_startdato", "help": "Frister regnes fra denne datoen.", "type": "date", "prompt": "Sykmeldingsdato (startdato)", "law_ref": "AML §4-6", "required": true}, {"key": "oppfolgingsplan_uke4", "help": "Planen skal beskrive tilretteleggingstiltak. Kopi sendes sykmelder.", "type": "yes_no_na", "prompt": "Er oppfølgingsplan opprettet innen 4 uker fra sykmeldingsdato?", "law_ref": "AML §4-6", "required": true, "severity_default": "critical"}, {"key": "sykmelder_kopi", "type": "yes_no_na", "prompt": "Er kopi av oppfølgingsplan sendt til sykmelder?", "required": true, "severity_default": "high"}, {"key": "dialogmote1_avholdt", "help": "Arbeidsgiver-initiert møte. Senest 7 uker etter sykmeldingens start ved 100% sykmelding.", "type": "yes_no_na", "prompt": "Er dialogmøte 1 avholdt innen 7 uker (gjelder 100% sykmelding)?", "law_ref": "AML §4-6", "required": true, "severity_default": "critical"}, {"key": "dialogmote1_dato", "type": "date", "prompt": "Dato for dialogmøte 1", "required": false}, {"key": "tilrettelegging_vurdert", "help": "Arbeidsgiver har plikt til å vurdere alle mulige tiltak — gradert sykmelding, tilpassede oppgaver, hjemmearbeid, omorganisering.", "type": "yes_no_na", "prompt": "Er alle mulige tilretteleggingstiltak i virksomheten vurdert?", "law_ref": "AML §4-6", "required": true, "severity_default": "critical"}, {"key": "tilrettelegging_beskrivelse", "type": "text", "prompt": "Hvilke tilretteleggingstiltak er vurdert og/eller iverksatt?", "law_ref": "AML §4-6", "required": true}, {"key": "nav_plan_sendt", "type": "yes_no_na", "prompt": "Er oppfølgingsplan sendt til NAV innen 9 uker?", "required": true, "severity_default": "high"}, {"key": "dialogmote2_behov", "help": "NAV innkaller til dialogmøte 2 ved behov. Arbeidsgiver plikter å møte.", "type": "yes_no_na", "prompt": "Er behov for dialogmøte 2 (NAV-initiert, ca. uke 26) avklart?", "required": false, "severity_default": "medium"}, {"key": "plan_oppdatert", "type": "yes_no_na", "prompt": "Er oppfølgingsplanen løpende oppdatert etter dialogmøter?", "required": true, "severity_default": "medium"}, {"key": "signatur_leder", "type": "signature", "prompt": "Nærmeste leders signatur", "required": true}, {"key": "signatur_arbeidstaker", "help": "Arbeidstaker kan avslå å signere — dokumenter frafall av signatur.", "type": "signature", "prompt": "Arbeidstakerens signatur", "required": false}]}'::jsonb,
  false, 'ved sykmelding over 4 uker',
  '{"fields": []}'::jsonb,
  array['AML § 4-6']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'ik-forskriften-arsgjennomgang', 'IK-forskriften — årsgjennomgang', 'Årlig gjennomgang av internkontrollen etter forskrift om systematisk helse-, miljø- og sikkerhetsarbeid (IK-f) § 5 nr. 1–8. Skal dokumentere at virksomheten har et reelt internkontrollsystem som dekker alle åtte bestanddelene loven krever.',
  '{"items": [{"key": "mal_bekrefte", "help": "§ 5 nr. 1: sørge for at de lover og forskrifter som gjelder for virksomheten er tilgjengelige, og ha oversikt over de krav som er av særlig viktighet.", "type": "yes_no_na", "prompt": "Er virksomhetens HMS-mål skriftlige og kjent for arbeidstakerne?", "law_ref": "IK-f § 5 nr. 1", "required": true, "severity_default": "medium"}, {"key": "ansvar_oppgaver", "type": "yes_no_na", "prompt": "Er det skriftlig dokumentert hvordan ansvar og oppgaver er fordelt for HMS-arbeidet?", "law_ref": "IK-f § 5 nr. 2", "required": true, "severity_default": "high"}, {"key": "medvirkning", "help": "Omfatter både opplæring, kompetansetiltak og reell medvirkning fra verneombud + AMU.", "type": "yes_no_na", "prompt": "Sørger virksomheten for at arbeidstakerne medvirker, og har tilstrekkelige kunnskaper og ferdigheter om HMS?", "law_ref": "IK-f § 5 nr. 3", "required": true, "severity_default": "high"}, {"key": "arbeidstakers_kunnskap", "type": "yes_no_na", "prompt": "Er det dokumentert hva arbeidstakerne skal kunne / vite om HMS, og er denne opplæringen gjennomført siste 12 mnd.?", "law_ref": "IK-f § 5 nr. 4", "required": true, "severity_default": "medium"}, {"key": "kartlegging", "help": "§ 5 nr. 5 = ROS-analyse. Skal foreligge skriftlig og være vurdert siste 12 mnd.", "type": "yes_no_na", "prompt": "Foreligger det en oppdatert kartlegging av farer og problemer, og vurdering av risiko, for HMS?", "law_ref": "IK-f § 5 nr. 5", "required": true, "severity_default": "critical"}, {"key": "tiltaksplan", "type": "yes_no_na", "prompt": "Er det skrevet handlingsplaner for å redusere identifiserte risikoer, og er tiltak iverksatt?", "law_ref": "IK-f § 5 nr. 6", "required": true, "severity_default": "critical"}, {"key": "rutiner_avvik", "help": "Avvikssystem + lukke-tiltak. Skal være skriftlig og operativt.", "type": "yes_no_na", "prompt": "Har virksomheten rutiner for å avdekke, rette opp og forebygge overtredelser av HMS-lovgivningen?", "law_ref": "IK-f § 5 nr. 7", "required": true, "severity_default": "critical"}, {"key": "gjennomgang", "help": "§ 5 nr. 8: ledelsens gjennomgang minst årlig.", "type": "yes_no_na", "prompt": "Gjennomgår virksomheten internkontrollen systematisk og sikrer at den fungerer som forutsatt?", "law_ref": "IK-f § 5 nr. 8", "required": true, "severity_default": "high"}, {"key": "samordning", "type": "yes_no_na", "prompt": "Hvis virksomheten har leverandører/innleide som arbeider på området: er det rutiner for samordning av HMS-arbeidet?", "law_ref": "IK-f § 6", "required": false, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / forbedringspunkter", "required": false}, {"key": "sign_hms", "type": "signature", "prompt": "HMS-leders signatur", "required": true}, {"key": "sign_dl", "type": "signature", "prompt": "Daglig leders signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['IK-f § 5', 'IK-f § 5 nr. 1', 'IK-f § 5 nr. 2', 'IK-f § 5 nr. 3', 'IK-f § 5 nr. 4', 'IK-f § 5 nr. 5', 'IK-f § 5 nr. 6', 'IK-f § 5 nr. 7', 'IK-f § 5 nr. 8', 'IK-f § 6']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'info-drofting-arsgjennomgang', 'Informasjon og drøfting — årlig gjennomgang', 'Årlig kontroll av at AML kap. 8 informasjons- og drøftingsplikten er praktisert: faste møter avholdt, vesentlige beslutninger drøftet før vedtak, og protokoll dokumentert.',
  '{"items": [{"key": "omfattes", "type": "yes_no_na", "prompt": "Er det avklart om virksomheten omfattes av plikten (≥50 arbeidstakere)?", "law_ref": "AML § 8-1", "required": true, "severity_default": "medium"}, {"key": "faste_moter", "type": "yes_no_na", "prompt": "Er det avholdt minimum to fellesmøter mellom ledelsen og tillitsvalgte siste 12 mnd.?", "law_ref": "AML § 8-1", "required": true, "severity_default": "high"}, {"key": "informasjon_skriftlig", "type": "yes_no_na", "prompt": "Er skriftlig informasjon sendt ut senest 5 virkedager før møtene?", "law_ref": "AML § 8-2", "required": true, "severity_default": "medium"}, {"key": "utvikling", "type": "yes_no_na", "prompt": "Er virksomhetens utvikling og forventede sysselsettingssituasjon presentert?", "law_ref": "AML § 8-2 (a, b)", "required": true, "severity_default": "high"}, {"key": "vesentlige_beslutninger", "type": "yes_no_na", "prompt": "Er vesentlige beslutninger som påvirker arbeidsforhold drøftet før vedtak?", "law_ref": "AML § 8-2 (c)", "required": true, "severity_default": "critical"}, {"key": "protokoll", "type": "yes_no_na", "prompt": "Er det ført protokoll fra hvert møte, signert av begge parter?", "law_ref": "AML § 8-2", "required": true, "severity_default": "high"}, {"key": "konfidensialitet", "type": "yes_no_na", "prompt": "Er konfidensialitetsmerking brukt korrekt — og taushetsplikten kommunisert?", "law_ref": "AML § 8-3", "required": true, "severity_default": "medium"}, {"key": "tvister", "type": "yes_no_na", "prompt": "Har det vært tvister eller innsigelser fra tillitsvalgte siste 12 mnd.?", "law_ref": "AML § 8-1", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner og forbedringspunkter", "required": false}, {"key": "sign_dl", "type": "signature", "prompt": "Daglig leders signatur", "required": true}, {"key": "sign_tv", "type": "signature", "prompt": "Tillitsvalgts signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['AML § 8-1', 'AML § 8-2', 'AML § 8-3']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'innleie-kvartalsgjennomgang', 'Innleie og midlertidig — kvartalsvis gjennomgang', 'Kvartalsvis kontroll av at innleie og midlertidige ansettelser etter AML §§ 14-9 og 14-12 oppfyller vilkårene, og at likebehandlingsprinsippet (§ 14-12a) er praktisert.',
  '{"items": [{"key": "midl_grunnlag", "type": "yes_no_na", "prompt": "Er det dokumentert grunnlag etter § 14-9 (1) for hver midlertidig avtale?", "law_ref": "AML § 14-9 (1)", "required": true, "severity_default": "critical"}, {"key": "midl_drofting", "type": "yes_no_na", "prompt": "Er bruken av midlertidig ansettelse drøftet med tillitsvalgte minst én gang siste 12 mnd.?", "law_ref": "AML § 14-9 (3)", "required": true, "severity_default": "high"}, {"key": "treaarsregelen", "type": "yes_no_na", "prompt": "Er det utført sjekk av 3-/4-årsregelen — ingen ansatt som passerer terskelen uten å være konvertert til fast?", "law_ref": "AML § 14-9 (7)", "required": true, "severity_default": "critical"}, {"key": "fortrinnsrett", "type": "yes_no_na", "prompt": "Er fortrinnsrett etter § 14-2 vurdert ved nyansettelser?", "law_ref": "AML § 14-2", "required": true, "severity_default": "high"}, {"key": "innleie_grunnlag", "help": "Generell innleie er ikke lovlig — krever konkret begrunnelse.", "type": "yes_no_na", "prompt": "Er innleie fra bemanningsforetak begrunnet i lovlig grunnlag (§ 14-12 (1) — vikariat / midlertidig behov; § 14-12 (2) — tariffavtale)?", "law_ref": "AML § 14-12", "required": true, "severity_default": "critical"}, {"key": "innleie_drofting", "type": "yes_no_na", "prompt": "Er innleie drøftet med tillitsvalgte (gjelder årlig + ved utvidet bruk)?", "law_ref": "AML § 14-12 (3)", "required": true, "severity_default": "high"}, {"key": "likebehandling", "type": "yes_no_na", "prompt": "Er likebehandlingsprinsippet praktisert — innleide har samme lønns-/arbeidsvilkår som om de var ansatt direkte?", "law_ref": "AML § 14-12a", "required": true, "severity_default": "critical"}, {"key": "solidaransvar", "type": "yes_no_na", "prompt": "Er det rutiner for å fange solidaransvar etter § 14-12c ved manglende oppfyllelse fra bemanningsforetaket?", "law_ref": "AML § 14-12c", "required": true, "severity_default": "high"}, {"key": "arbavtaler", "type": "yes_no_na", "prompt": "Foreligger skriftlig arbeidsavtale etter § 14-5 for samtlige arbeidstakere — fast og midlertidig?", "law_ref": "AML § 14-5", "required": true, "severity_default": "critical"}, {"key": "konkurranseklausul", "type": "yes_no_na", "prompt": "Er aktive konkurranse-/kundeklausuler vurdert etter kap. 14 A — gyldighet og kompensasjon?", "law_ref": "AML § 14A-1", "required": false, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner", "required": false}, {"key": "sign_hr", "type": "signature", "prompt": "HR-ansvarliges signatur", "required": true}, {"key": "sign_tv", "type": "signature", "prompt": "Tillitsvalgts signatur", "required": true}]}'::jsonb,
  false, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 14-2', 'AML § 14-5', 'AML § 14-9', 'AML § 14-12', 'AML § 14-12a', 'AML § 14-12c', 'AML § 14A-1']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'innleie-sjekk', 'Innleie fra bemanningsforetak – sjekk', 'Sjekkliste ved bruk av innleid arbeidskraft fra bemanningsforetak. Dokumenterer juridisk grunnlag, likebehandling og drøftingsplikt (AML §14-12, §14-12a, §14-12c).',
  '{"items": [{"key": "foretak_navn", "type": "text", "prompt": "Navn på bemanningsforetaket", "required": true}, {"key": "foretak_registrert", "help": "Sjekk register.arbeidstilsynet.no/bemanningsforetak. Uregistrerte foretak er forbudt.", "type": "yes_no_na", "prompt": "Er bemanningsforetaket registrert i Arbeidstilsynets register over bemanningsforetak?", "law_ref": "AML §14-12", "required": true, "severity_default": "critical"}, {"key": "juridisk_grunnlag", "help": "Fast ansatt arbeidstaker som midlertidig er fraværende, eller vilkårene i §14-9 for midlertidig ansettelse er til stede.", "type": "yes_no_na", "prompt": "Er det juridiske grunnlaget for innleie vurdert og dokumentert?", "law_ref": "AML §14-12", "required": true, "severity_default": "critical"}, {"key": "innleieperiode", "type": "text", "prompt": "Planlagt innleieperiode (dd.mm.åååå – dd.mm.åååå)", "required": true}, {"key": "stilling_funksjon", "type": "text", "prompt": "Stilling og funksjon den innleide utfører", "required": true}, {"key": "likebehandling_sikret", "help": "§14-12a: innleid arbeidstaker har krav på lønn og arbeidsvilkår som om vedkommende var ansatt hos innleier.", "type": "yes_no_na", "prompt": "Er likebehandling på lønn og arbeidsvilkår sikret — minst tilsvarende fast ansatt?", "law_ref": "AML §14-12a", "required": true, "severity_default": "critical"}, {"key": "drofting_gjennomfort", "help": "Drøftingsplikten gjelder ved planlagt innleie og i den årlige gjennomgangen.", "type": "yes_no_na", "prompt": "Er bruk av innleide drøftet med tillitsvalgte?", "law_ref": "AML §14-12c", "required": true, "severity_default": "high"}, {"key": "drofting_dato", "type": "date", "prompt": "Dato for drøfting med tillitsvalgte", "law_ref": "AML §14-12c", "required": false}, {"key": "ansatte_informert", "type": "yes_no_na", "prompt": "Er ansatte informert om omfanget av innleie?", "law_ref": "AML §14-12c", "required": true, "severity_default": "medium"}, {"key": "signatur", "type": "signature", "prompt": "HR-/leder signatur", "required": true}]}'::jsonb,
  false, 'ved bruk av innleid arbeidskraft',
  '{"fields": []}'::jsonb,
  array['AML § 14-12', 'AML § 14-12a', 'AML § 14-12c']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'internkontroll-arsgjennomgang', 'Internkontroll – årsgjennomgang', 'Årlig systematisk gjennomgang av internkontrollen (IK-forskriften §5 nr. 8). Sentral artefakt for tilsyn.',
  '{"items": [{"key": "mal_oppfolging", "type": "yes_no_na", "prompt": "Er HMS-mål satt for året evaluert?", "law_ref": "IK-forskriften §5 nr. 4", "required": true, "severity_default": "medium"}, {"key": "risikovurdering_oppdatert", "type": "yes_no_na", "prompt": "Er risikovurderinger oppdatert siste 12 mnd?", "law_ref": "IK-forskriften §5 nr. 6", "required": true, "severity_default": "high"}, {"key": "verneombud_aktivt", "type": "yes_no_na", "prompt": "Har verneombudet vært aktivt deltakende?", "law_ref": "AML §6-2", "required": true, "severity_default": "medium"}, {"key": "amu_protokoll_signert", "help": "Hvis virksomheten har AMU-plikt etter §7-1.", "type": "yes_no_na", "prompt": "Er AMU-protokoll for året undertegnet?", "law_ref": "AML §7-2", "required": false, "severity_default": "medium"}, {"key": "avvik_handlingsplan", "type": "yes_no_na", "prompt": "Er avvikshåndtering og handlingsplan ført løpende?", "law_ref": "IK-forskriften §5 nr. 7", "required": true, "severity_default": "high"}, {"key": "bht_dialog", "help": "Hvis virksomheten har BHT-plikt.", "type": "yes_no_na", "prompt": "Har bedriftshelsetjenesten levert årsrapport?", "law_ref": "AML §3-3", "required": false, "severity_default": "medium"}, {"key": "forbedringsforslag", "type": "text", "prompt": "Hva er identifisert som hovedforbedring for neste år?", "required": true}, {"key": "signatur_dagligleder", "type": "signature", "prompt": "Daglig leders signatur", "law_ref": "IK-forskriften §5 nr. 8", "required": true}]}'::jsonb,
  true, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 3-1', 'AML § 3-3', 'AML § 6-2', 'AML § 7-2', 'IK-f § 5 nr. 4', 'IK-f § 5 nr. 6', 'IK-f § 5 nr. 7', 'IK-f § 5 nr. 8']::text[],
  'draft', 'internkontroll'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'kontrolltiltak-arsgjennomgang', 'Kontrolltiltak — årlig gjennomgang', 'Årlig kontroll av at alle aktive kontrolltiltak fortsatt har saklig grunn, er forholdsmessige og er forsvarlig dokumentert (AML §§ 9-1, 9-2). Identifiserer tiltak som har «vokst» utover opprinnelig formål.',
  '{"items": [{"key": "tiltaksoversikt", "help": "Oversikten skal omfatte tiltak innført av leverandører/IT også.", "type": "yes_no_na", "prompt": "Er det en oppdatert oversikt over alle aktive kontrolltiltak (kamera, GPS, tidsreg., logging, e-post-innsyn, rusmiddeltest)?", "law_ref": "AML § 9-1", "required": true, "severity_default": "high"}, {"key": "vurderingsmal_lagt", "type": "yes_no_na", "prompt": "Foreligger det skriftlig saklighets- og forholdsmessighetsvurdering for hvert tiltak?", "law_ref": "AML § 9-1 (1)", "required": true, "severity_default": "critical"}, {"key": "formal_avgrenset", "type": "yes_no_na", "prompt": "Er formålet for hvert tiltak konkret avgrenset (ikke «generell sikkerhet»)?", "law_ref": "GDPR Art. 5 + AML § 9-1", "required": true, "severity_default": "high"}, {"key": "drofting_dok", "type": "yes_no_na", "prompt": "Er drøftingen med tillitsvalgte / AMU dokumentert (referat) for hvert tiltak?", "law_ref": "AML § 9-2 (1)", "required": true, "severity_default": "critical"}, {"key": "info_arbeidstakere", "type": "yes_no_na", "prompt": "Har berørte arbeidstakere fått skriftlig informasjon om formål, omfang og varighet?", "law_ref": "AML § 9-2 (2)", "required": true, "severity_default": "high"}, {"key": "dpia", "type": "yes_no_na", "prompt": "Er DPIA (Art. 35) gjennomført der det kreves?", "law_ref": "GDPR Art. 35", "required": true, "severity_default": "high"}, {"key": "behandlingsgrunnlag", "type": "yes_no_na", "prompt": "Er behandlingsgrunnlaget etter GDPR Art. 6 dokumentert i behandlingsprotokollen?", "law_ref": "GDPR Art. 6 + 30", "required": true, "severity_default": "high"}, {"key": "tilgang", "type": "yes_no_na", "prompt": "Er tilgangen til kontrolldata begrenset til personer med tjenstlig behov?", "law_ref": "AML § 9-1 + GDPR Art. 32", "required": true, "severity_default": "high"}, {"key": "lagringstid", "type": "yes_no_na", "prompt": "Er lagringstid satt så kort som mulig og dokumentert?", "law_ref": "GDPR Art. 5 (1) e", "required": true, "severity_default": "high"}, {"key": "epost_innsyn", "type": "yes_no_na", "prompt": "Hvis det har vært innsyn i ansattes e-post: er forskriftens vilkår oppfylt og varsel gitt?", "law_ref": "AML § 9-3 + FOR-2018-07-02-1107", "required": false, "severity_default": "critical"}, {"key": "evaluering", "type": "yes_no_na", "prompt": "Er det utført løpende evaluering av om vilkårene fortsatt er til stede?", "law_ref": "AML § 9-2 (3)", "required": true, "severity_default": "medium"}, {"key": "utgatte", "type": "yes_no_na", "prompt": "Er kontrolltiltak som ikke lenger har saklig grunn avviklet?", "law_ref": "AML § 9-1", "required": true, "severity_default": "high"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / forbedringspunkter", "required": false}, {"key": "sign_dpo", "type": "signature", "prompt": "Personvernombudets signatur (eller behandlingsansvarlig)", "required": true}, {"key": "sign_tv", "type": "signature", "prompt": "Tillitsvalgt / verneombud — signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['AML § 9-1', 'AML § 9-2', 'AML § 9-3', 'GDPR Art. 6', 'GDPR Art. 35']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'kontrolltiltak-evaluering', 'Kontrolltiltak – evaluering', 'Periodisk evaluering av kontrolltiltak overfor ansatte (kamera, GPS, datakontroll m.m.). Kun relevant for virksomheter som benytter slike tiltak. Dokumenterer drøfting, informasjon og evaluering (AML §9-1 + §9-2).',
  '{"items": [{"key": "tiltak_type", "type": "text", "prompt": "Hvilke kontrolltiltak benyttes i virksomheten? (beskriv)", "law_ref": "AML §9-1", "required": true}, {"key": "saklig_grunnlag", "help": "Saklig grunn kan f.eks. være sikkerhet, vern av forretningshemmeligheter eller kontroll av arbeidstid.", "type": "yes_no_na", "prompt": "Er tiltaket saklig begrunnet i virksomhetens forhold?", "law_ref": "AML §9-1", "required": true, "severity_default": "critical"}, {"key": "forholdsmessig", "type": "yes_no_na", "prompt": "Er tiltaket forholdsmessig — ikke mer inngripende enn nødvendig for formålet?", "law_ref": "AML §9-1", "required": true, "severity_default": "critical"}, {"key": "droftet_tillitsvalgte", "type": "yes_no_na", "prompt": "Er kontrolltiltaket drøftet med tillitsvalgte?", "law_ref": "AML §9-2", "required": true, "severity_default": "critical"}, {"key": "drofting_dato", "type": "date", "prompt": "Dato for drøfting med tillitsvalgte", "law_ref": "AML §9-2", "required": false}, {"key": "ansatte_informert", "type": "yes_no_na", "prompt": "Er ansatte informert om: hva overvåkes, formål, hvem har tilgang, og hvor lenge data lagres?", "law_ref": "AML §9-2", "required": true, "severity_default": "high"}, {"key": "evaluering_gjennomfort", "type": "yes_no_na", "prompt": "Er tiltaket evaluert i inneværende periode (§9-2 krever periodisk evaluering)?", "law_ref": "AML §9-2", "required": true, "severity_default": "high"}, {"key": "evaluering_dato", "type": "date", "prompt": "Dato for denne evalueringen", "required": true}, {"key": "personvern_vurdert", "help": "Anbefalt ved systematisk overvåkning (GDPR Art. 35). Obligatorisk ved høy risiko for de registrerte.", "type": "yes_no_na", "prompt": "Er personvernkonsekvenser (DPIA) vurdert?", "required": false, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Kommentarer til evalueringen eller planlagte endringer", "required": false}, {"key": "signatur", "type": "signature", "prompt": "HMS-ansvarlig / leder signatur", "required": true}]}'::jsonb,
  false, 'årlig (eller ved endring av tiltak)',
  '{"fields": []}'::jsonb,
  array['AML § 9-1', 'AML § 9-2']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'likestilling-arssjekk', 'Likestillingsredegjørelse – årssjekk', 'Årlig sjekk av likestillings- og ikke-diskrimineringsredegjørelse (Likestillings- og diskrimineringsloven §26 + AML §13-1). Obligatorisk for virksomheter med 50 eller flere ansatte.',
  '{"items": [{"key": "antall_ansatte", "help": "Rapporteringsplikt gjelder fra 50 ansatte. 20–49 ansatte kan ha plikt per tariffavtale.", "type": "number", "prompt": "Totalt antall fast ansatte", "required": true}, {"key": "lonnsgap_kartlagt", "help": "LDL §26: aktivitetsplikt inkluderer kartlegging av lønn per kjønn.", "type": "yes_no_na", "prompt": "Er lønnsstatistikk kartlagt og fordelt på kjønn og stillingsnivå?", "law_ref": "AML §13-1", "required": true, "severity_default": "critical"}, {"key": "lederandel_kartlagt", "type": "yes_no_na", "prompt": "Er andelen kvinner og menn i lederposisjoner kartlagt?", "required": true, "severity_default": "high"}, {"key": "deltid_kartlagt", "type": "yes_no_na", "prompt": "Er bruk av deltid per kjønn kartlagt?", "required": true, "severity_default": "high"}, {"key": "ufrivillig_deltid_kartlagt", "help": "§14-3: deltidsansatte har fortrinnsrett til økt stilling fremfor ny ansettelse.", "type": "yes_no_na", "prompt": "Er ufrivillig deltid kartlagt og berørte ansatte tilbudt økt stilling/fortrinnsrett?", "law_ref": "AML §14-3", "required": false, "severity_default": "medium"}, {"key": "forskjeller_analysert", "type": "yes_no_na", "prompt": "Er identifiserte lønns- og karriereforskjeller mellom kjønn analysert?", "required": true, "severity_default": "high"}, {"key": "tiltak_planlagt", "type": "yes_no_na", "prompt": "Er konkrete tiltak for å utjevne eventuelle ulikheter planlagt?", "required": true, "severity_default": "high"}, {"key": "tiltak_beskrivelse", "type": "text", "prompt": "Beskriv planlagte likestillingstiltak", "required": false}, {"key": "redegjorelse_publisert", "help": "LDL §26: redegjørelsen skal offentliggjøres. Diskrimineringsnemnda kan sanksjonere manglende publisering.", "type": "yes_no_na", "prompt": "Er likestillingsredegjørelsen offentliggjort (årsrapport, nettside eller tilsvarende)?", "required": true, "severity_default": "critical"}, {"key": "publisert_dato", "type": "date", "prompt": "Dato for offentliggjøring av redegjørelsen", "required": false}, {"key": "forrige_aar_effekt", "type": "yes_no_na", "prompt": "Er effekt av fjorårets likestillingstiltak evaluert?", "required": false, "severity_default": "medium"}, {"key": "signatur", "type": "signature", "prompt": "Daglig leder / HR-ansvarlig signatur", "required": true}]}'::jsonb,
  false, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 13-1', 'AML § 13-7', 'Likestillings- og diskrimineringsloven § 26']::text[],
  'draft', null
) on conflict (pack, slug) do update set
