  'aml-amu', 'maskinsikkerhet-sjekk', 'Maskinsikkerhet-sjekk', 'Periodisk kontroll av maskinsikkerhet — verneanordninger, nødstopp, dokumentasjon, vedlikehold (AML §4-4 (1) + Arbeidsutstyrsforskriften).',
  '{"items": [{"key": "maskin_id", "type": "text", "prompt": "Hvilken maskin / utstyr er kontrollert? (ID eller navn)", "required": true}, {"key": "verneanordning_funksjon", "type": "yes_no_na", "prompt": "Fungerer verneanordninger som forutsatt?", "law_ref": "AML §4-4 (1)", "required": true, "severity_default": "critical"}, {"key": "noedstopp_test", "type": "yes_no_na", "prompt": "Er nødstopp testet og responderer?", "required": true, "severity_default": "critical"}, {"key": "dokumentasjon_oppdatert", "type": "yes_no_na", "prompt": "Er bruksanvisning og samsvarserklæring tilgjengelig?", "required": true, "severity_default": "high"}, {"key": "vedlikehold_journal", "type": "yes_no_na", "prompt": "Er siste vedlikehold dokumentert?", "required": true, "severity_default": "medium"}, {"key": "foto", "type": "photo", "prompt": "Bilder av kontrollert utstyr", "required": false}, {"key": "signatur", "type": "signature", "prompt": "Inspektørens signatur", "required": true}]}'::jsonb,
