insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'onboarding-hms-opplaering', 'Onboarding – HMS-opplæring', 'Sjekkliste for HMS-opplæring av ny ansatt før selvstendig arbeid (AML §3-2 (1) b + §3-3 + arbeidstakers medvirkningsplikt §2-3).',
  '{"items": [{"key": "intro_arb_omr", "type": "yes_no_na", "prompt": "Har den ansatte fått omvisning og gjennomgang av arbeidsplassen?", "law_ref": "AML §3-2 (1) b", "required": true, "severity_default": "high"}, {"key": "verneutstyr_opplaering", "type": "yes_no_na", "prompt": "Er bruk av personlig verneutstyr vist og praktisert?", "law_ref": "AML §3-2 (1) a", "required": true, "severity_default": "critical"}, {"key": "noedutgang", "type": "yes_no_na", "prompt": "Er nødutganger og samlingsplass vist?", "law_ref": "AML §4-4", "required": true, "severity_default": "high"}, {"key": "kjemikalier_intro", "help": "Hvis arbeidet involverer kjemikalier.", "type": "yes_no_na", "prompt": "Er stoffkartotek og kjemiske risikoer gjennomgått?", "law_ref": "AML §4-5", "required": false, "severity_default": "high"}, {"key": "verneombud_kontakt", "type": "text", "prompt": "Hvem er den ansattes verneombud (navn + kontakt)?", "law_ref": "AML §6-1", "required": true}, {"key": "signatur_ansatt", "type": "signature", "prompt": "Den ansattes signatur", "law_ref": "AML §2-3", "required": true}, {"key": "signatur_naermeste_leder", "type": "signature", "prompt": "Nærmeste leders signatur", "law_ref": "AML §2-1", "required": true}]}'::jsonb,
  true, 'ved tilsetting',
  '{"fields": []}'::jsonb,
  array['AML § 2-3', 'AML § 3-2', 'AML § 4-4', 'AML § 4-5', 'AML § 6-1']::text[],
  'draft', 'ansettelse'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
