  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'oppsigelse-droftelse-sjekk', 'Drøftelse før oppsigelse — sjekkliste', 'Sjekkliste som fylles ut FØR vedtak om oppsigelse treffes — verifiserer at AML § 15-1 (drøftelsesplikt), § 15-4 (formkrav) og § 15-7 (saklighetskrav) er ivaretatt.',
  '{"items": [{"key": "sak_grunnlag", "help": "Saklig grunn må foreligge — i arbeidstakers, virksomhetens eller arbeidsgivers forhold.", "type": "yes_no_na", "prompt": "Er det skrevet ned saklig grunn for oppsigelsen før samtalen?", "law_ref": "AML § 15-7", "required": true, "severity_default": "critical"}, {"key": "annet_arbeid", "help": "Krav ved oppsigelse pga. virksomhetens forhold (nedbemanning).", "type": "yes_no_na", "prompt": "Er det vurdert om det finnes annet passende arbeid (§ 15-7 (2))?", "law_ref": "AML § 15-7 (2)", "required": true, "severity_default": "critical"}, {"key": "tilrettelegging", "type": "yes_no_na", "prompt": "Ved oppsigelse av sykmeldt: er § 4-6 tilretteleggingsplikten dokumentert oppfylt?", "law_ref": "AML § 4-6 + § 15-8", "required": false, "severity_default": "high"}, {"key": "innkalling", "type": "yes_no_na", "prompt": "Er skriftlig innkalling sendt minst 5 virkedager før samtalen, med tema og rett til å la seg bistå?", "law_ref": "AML § 15-1", "required": true, "severity_default": "high"}, {"key": "forhandsvarsel", "type": "yes_no_na", "prompt": "Er arbeidstakeren informert om de faktiske forhold som vurderes (uten konklusjon)?", "law_ref": "AML § 15-1", "required": true, "severity_default": "high"}, {"key": "tillitsvalgt", "type": "yes_no_na", "prompt": "Er drøftelse også gjennomført med tillitsvalgt (der dette er aktuelt)?", "law_ref": "AML § 15-1 (1)", "required": true, "severity_default": "high"}, {"key": "utvalgskrit", "type": "yes_no_na", "prompt": "Ved nedbemanning: er utvalgskriteriene drøftet og dokumentert (ansiennitet, kompetanse, sosiale hensyn)?", "law_ref": "AML § 15-1 + Hovedavtalen", "required": false, "severity_default": "high"}, {"key": "konsekvens", "type": "yes_no_na", "prompt": "Er konsekvensene for arbeidstakeren (sosiale, økonomiske, helse) drøftet?", "law_ref": "AML § 15-1", "required": true, "severity_default": "medium"}, {"key": "protokoll", "type": "yes_no_na", "prompt": "Er det ført protokoll fra samtalen, signert av begge parter?", "law_ref": "AML § 15-1", "required": true, "severity_default": "high"}, {"key": "vedtak_pause", "type": "yes_no_na", "prompt": "Bekreft at vedtak ikke ble truffet i selve samtalen (krav til reell ny vurdering før vedtak).", "law_ref": "AML § 15-1", "required": true, "severity_default": "critical"}, {"key": "formkrav", "type": "yes_no_na", "prompt": "Er det utformet skriftlig oppsigelsesbrev som oppfyller § 15-4 (rett til forhandling, søksmål, frister, retten til å stå i stilling)?", "law_ref": "AML § 15-4", "required": true, "severity_default": "critical"}, {"key": "overlevering", "type": "single_select", "prompt": "Skal oppsigelsesbrevet overleveres personlig eller sendes rekommandert?", "law_ref": "AML § 15-4 (2)", "required": true, "severity_default": "high"}, {"key": "sluttattest_planlagt", "type": "yes_no_na", "prompt": "Er sluttattest etter § 15-15 forberedt (mal valgt, sluttdato, oppgaver)?", "law_ref": "AML § 15-15", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Kommentarer / særlige forhold", "required": false}, {"key": "sign_hr", "type": "signature", "prompt": "HR-ansvarliges signatur", "required": true}, {"key": "sign_leder", "type": "signature", "prompt": "Beslutningstakers signatur", "required": true}]}'::jsonb,
  false, 'ad_hoc',
  '{"fields": []}'::jsonb,
  array['AML § 15-1', 'AML § 15-4', 'AML § 15-7', 'AML § 15-15']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'oppsigelse-drofting-sjekk', 'Oppsigelse – drøftelsessjekk', 'Sjekkliste for drøftelsesmøte FØR beslutning om oppsigelse (AML §15-1). Manglende drøftelse er det vanligste grunnlaget for at oppsigelse kjennes ugyldig. Én utfylling per oppsigelsessak.',
  '{"items": [{"key": "stilling_rolle", "help": "Bruk stillingstittel, ikke personnavn, for å beskytte den ansattes personvern i systemet.", "type": "text", "prompt": "Stilling/rolle som berøres (ikke navn — personvern)", "required": true}, {"key": "drofting_tilbudt", "type": "yes_no_na", "prompt": "Er drøftelsesmøte tilbudt i tråd med AML §15-1?", "law_ref": "AML §15-1", "required": true, "severity_default": "critical"}, {"key": "innkalling_skriftlig", "type": "yes_no_na", "prompt": "Var innkallingen skriftlig og ga arbeidstaker tilstrekkelig tid til forberedelse?", "law_ref": "AML §15-1", "required": true, "severity_default": "high"}, {"key": "tillitsvalgt_tilbudt", "type": "yes_no_na", "prompt": "Ble arbeidstaker tilbudt å ha tillitsvalgt eller annen rådgiver til stede?", "law_ref": "AML §15-1", "required": true, "severity_default": "high"}, {"key": "arbeidstaker_tilstede", "help": "Nei er mulig — arbeidstaker kan avslå drøftelse. Dokumenter avslaget.", "type": "yes_no_na", "prompt": "Var arbeidstaker til stede på møtet?", "required": true}, {"key": "saken_presentert", "type": "yes_no_na", "prompt": "Ble saksgrunnlaget (grunnlag for mulig oppsigelse) presentert og drøftet?", "law_ref": "AML §15-1", "required": true, "severity_default": "critical"}, {"key": "arbeidstaker_fikk_svare", "type": "yes_no_na", "prompt": "Fikk arbeidstaker mulighet til å presentere sitt syn før beslutning?", "required": true, "severity_default": "critical"}, {"key": "drofting_dato", "type": "date", "prompt": "Dato for drøftelsesmøtet", "law_ref": "AML §15-1", "required": true}, {"key": "oppsigelse_etter_mote", "type": "yes_no_na", "prompt": "Ble oppsigelse besluttet og gitt ETTER møtet (ikke i selve drøftelsesmøtet)?", "law_ref": "AML §15-1", "required": true, "severity_default": "high"}, {"key": "saklighet_vurdert", "type": "yes_no_na", "prompt": "Er saklighetsgrunnlaget for oppsigelsen vurdert og dokumentert?", "law_ref": "AML §15-7", "required": true, "severity_default": "critical"}, {"key": "formkrav_sjekket", "help": "§15-4: oppsigelsen skal inneholde opplysninger om rett til forhandling og søksmål, søksmålsfrister og fortrinnsrett etter §14-2.", "type": "yes_no_na", "prompt": "Er oppsigelsens form og innhold kontrollert (skriftlig, inneholder §15-4-opplysninger)?", "law_ref": "AML §15-4", "required": true, "severity_default": "high"}, {"key": "oppsigelsesdato", "type": "date", "prompt": "Dato oppsigelsen ble gitt", "law_ref": "AML §15-4", "required": true}, {"key": "signatur_leder", "type": "signature", "prompt": "Leder / HR-ansvarlig signatur", "required": true}]}'::jsonb,
  false, 'ved oppsigelse',
  '{"fields": []}'::jsonb,
  array['AML § 15-1', 'AML § 15-4', 'AML § 15-7']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'personskade-kvartalsgjennomgang', 'Personskader — kvartalsvis melderutinekontroll', 'Kvartalsvis kontroll av at AML §§ 5-1, 5-2 og 5-3 er praktisert: alle hendelser registrert, alvorlige skader varslet rettidig til Arbeidstilsynet, og NAV-skademelding sendt der det kreves.',
  '{"items": [{"key": "register_komplett", "type": "yes_no_na", "prompt": "Er alle registrerte skader/sykdommer i siste kvartal lagt inn i personskaderegistret med fullstendig informasjon?", "law_ref": "AML § 5-1", "required": true, "severity_default": "critical"}, {"key": "nesten_ulykker", "help": "Underregistrering av nesten-ulykker er typisk pålegg-grunn — gir tapt læring.", "type": "yes_no_na", "prompt": "Er nesten-ulykker (uten fysisk skade) også registrert?", "law_ref": "AML § 5-1 + IK-f § 5", "required": true, "severity_default": "high"}, {"key": "varsel_alvorlig", "type": "yes_no_na", "prompt": "Er alle alvorlige skader / dødsfall varslet til Arbeidstilsynet snarest mulig (§ 5-2)?", "law_ref": "AML § 5-2", "required": true, "severity_default": "critical"}, {"key": "politi_dødsfall", "type": "yes_no_na", "prompt": "Er politiet varslet ved dødsfall?", "law_ref": "AML § 5-2", "required": false, "severity_default": "critical"}, {"key": "nav_melding", "type": "yes_no_na", "prompt": "Er det sendt skademelding til NAV for skader som omfattes av folketrygdloven § 13-14?", "law_ref": "Folketrygdloven § 13-14", "required": true, "severity_default": "high"}, {"key": "rotaarsak", "type": "yes_no_na", "prompt": "Er det utført rotårsaksanalyse for alvorlige hendelser i kvartalet?", "law_ref": "IK-f § 5 nr. 7", "required": true, "severity_default": "high"}, {"key": "tiltak_dokumentert", "type": "yes_no_na", "prompt": "Er konkrete forebyggende tiltak iverksatt og dokumentert med ansvar og frist?", "law_ref": "AML § 3-1 + IK-f § 5", "required": true, "severity_default": "high"}, {"key": "tiltak_effekt", "type": "yes_no_na", "prompt": "Er effekten av tidligere tiltak verifisert (lukket etter dokumentert effekt)?", "law_ref": "IK-f § 5 nr. 7", "required": true, "severity_default": "medium"}, {"key": "vo_informert", "type": "yes_no_na", "prompt": "Er verneombud informert om alle hendelser?", "law_ref": "AML § 6-2", "required": true, "severity_default": "high"}, {"key": "amu_orientert", "type": "yes_no_na", "prompt": "Er AMU orientert med statistikk og trender for kvartalet?", "law_ref": "AML § 7-2 (e)", "required": true, "severity_default": "medium"}, {"key": "arbeidstaker_medvirkning", "type": "yes_no_na", "prompt": "Har arbeidstakere som har vært involvert deltatt i etter-arbeidet (medvirkning)?", "law_ref": "AML § 5-3", "required": true, "severity_default": "medium"}, {"key": "statistikk_trend", "type": "yes_no_na", "prompt": "Vurderer statistikken (frekvens / alvorlighet / type) en negativ trend som krever overordnet tiltak?", "law_ref": "AML § 3-1 (2c)", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / særlige forhold", "required": false}, {"key": "sign_hms", "type": "signature", "prompt": "HMS-leders signatur", "required": true}, {"key": "sign_vo", "type": "signature", "prompt": "Verneombudets signatur", "required": true}]}'::jsonb,
  false, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 5-1', 'AML § 5-2', 'AML § 5-3', 'Folketrygdloven § 13-14']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'psykososial-pulsmaling', 'Psykososial pulsmåling', 'Halvårlig pulsmåling av psykososiale forhold (AML §4-3). Supplerer anonym survey for ikke-observable forhold.',
  '{"items": [{"key": "trakassering_observert", "type": "yes_no_na", "prompt": "Er det observert eller meldt om trakassering eller utilbørlig opptreden?", "law_ref": "AML §4-3 (3)", "required": true, "severity_default": "critical"}, {"key": "arbeidsbelastning_balansert", "type": "yes_no_na", "prompt": "Oppleves arbeidsbelastningen som forsvarlig?", "law_ref": "AML §4-3", "required": true, "severity_default": "high"}, {"key": "ledelse_dialog", "type": "yes_no_na", "prompt": "Har de ansatte regelmessig dialog med leder om arbeidssituasjon?", "required": false, "severity_default": "medium"}, {"key": "inkluderende_kultur", "type": "yes_no_na", "prompt": "Oppleves arbeidsmiljøet som inkluderende?", "required": false, "severity_default": "medium"}, {"key": "aapne_temaer", "type": "text", "prompt": "Hvilke psykososiale temaer er aktive nå? (Skriv ikke personidentifiserende helseopplysninger.)", "required": false}, {"key": "signatur_verneombud", "type": "signature", "prompt": "Verneombudets signatur", "law_ref": "AML §6-2", "required": true}]}'::jsonb,
  true, 'halvårlig',
  '{"fields": []}'::jsonb,
  array['AML § 4-2', 'AML § 4-3', 'AML § 6-2']::text[],
  'draft', 'psykososialt'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'skade-sykdom-register-sjekk', 'Skade- og sykdomsregister – kvartalssjekk', 'Kvartalsvis kontroll av at skade- og sykdomsregisteret er oppdatert og at meldeplikt overholdes (AML §5-1 + §5-2 + §5-3). Grunnlag for AMU-rapportering.',
  '{"items": [{"key": "register_eksisterer", "type": "yes_no_na", "prompt": "Eksisterer et skriftlig (eller digitalt) skade- og sykdomsregister?", "law_ref": "AML §5-1", "required": true, "severity_default": "critical"}, {"key": "register_oppdatert", "type": "yes_no_na", "prompt": "Er alle personskader og nestenulykker siden forrige sjekk registrert?", "law_ref": "AML §5-1", "required": true, "severity_default": "critical"}, {"key": "alvorlig_hendelse_meldt", "help": "Straks-varsel ved alvorlig personskade, arbeidsulykke med mulig dødelig utfall eller alvorlig feil ved teknisk innretning.", "type": "yes_no_na", "prompt": "Er eventuelle alvorlige personskader straks varslet til Arbeidstilsynet og politiet?", "law_ref": "AML §5-2", "required": true, "severity_default": "critical"}, {"key": "yrkessykdom_meldt", "help": "Arbeidsgiver og lege har selvstendig meldeplikt ved mistanke om yrkessykdom.", "type": "yes_no_na", "prompt": "Er behandlende lege varslet ved mistanke om yrkessykdom?", "law_ref": "AML §5-3", "required": true, "severity_default": "high"}, {"key": "antall_personskader", "type": "number", "prompt": "Antall registrerte personskader dette kvartalet", "law_ref": "AML §5-1", "required": true}, {"key": "antall_nestenulykker", "type": "number", "prompt": "Antall registrerte nestenulykker dette kvartalet", "required": true}, {"key": "amu_informert", "help": "Gjelder for virksomheter med AMU (≥50 ansatte).", "type": "yes_no_na", "prompt": "Er AMU informert om registerstatus?", "law_ref": "AML §7-2", "required": false, "severity_default": "medium"}, {"key": "trend_kommentar", "type": "text", "prompt": "Observasjoner, trender eller årsaksanalyse fra perioden", "required": false}, {"key": "signatur", "type": "signature", "prompt": "HMS-ansvarlig signatur", "required": true}]}'::jsonb,
  false, 'kvartalsvis',
  '{"fields": []}'::jsonb,
  array['AML § 5-1', 'AML § 5-2', 'AML § 5-3']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'stoffkartotek-runde', 'Stoffkartotek-runde', 'Årlig kontroll av stoffkartotek, merking, oppbevaring, verneutstyr og risikovurdering for kjemikalier (AML §4-5 + Stoffkartotekforskriften).',
  '{"items": [{"key": "stoffkartotek_oppdatert", "type": "yes_no_na", "prompt": "Er stoffkartoteket oppdatert siste 12 mnd?", "law_ref": "AML §4-5", "required": true, "severity_default": "high"}, {"key": "merking_korrekt", "type": "yes_no_na", "prompt": "Er kjemikalier korrekt merket (CLP)?", "law_ref": "AML §4-5", "required": true, "severity_default": "critical"}, {"key": "oppbevaring_forsvarlig", "type": "yes_no_na", "prompt": "Er oppbevaring og separasjon forsvarlig?", "required": true, "severity_default": "critical"}, {"key": "verneutstyr_dedikert", "type": "yes_no_na", "prompt": "Er dedikert verneutstyr for kjemikaliebruk tilgjengelig?", "law_ref": "AML §3-2 (1) a", "required": true, "severity_default": "critical"}, {"key": "risikovurdering_pr_stoff", "type": "yes_no_na", "prompt": "Er risikovurdering gjort for hvert farlig stoff?", "law_ref": "IK-forskriften §5 nr. 6", "required": true, "severity_default": "high"}, {"key": "eksponeringsmaling", "type": "yes_no_na", "prompt": "Er eksponeringsmålinger gjennomført der pålagt?", "required": false, "severity_default": "high"}, {"key": "foto", "type": "photo", "prompt": "Bilder fra runden", "required": false}, {"key": "signatur", "type": "signature", "prompt": "Verneombud + HMS-leder signatur", "required": true}]}'::jsonb,
  true, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 3-2', 'AML § 4-5', 'IK-f § 5 nr. 6']::text[],
  'draft', 'fysisk'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'tilsetting-mindrearig-sjekk', 'Tilsetting av mindreårig – sjekk', 'Sjekkliste som må fullføres FØR første arbeidsdag for personer under 18 år (AML kap 11).',
  '{"items": [{"key": "alder_bekreftet", "type": "yes_no_na", "prompt": "Er alderen til den ansatte bekreftet (kopi av legitimasjon)?", "law_ref": "AML §11-1", "required": true, "severity_default": "critical"}, {"key": "arbeidstid_innenfor_grenser", "help": "Maks 8t/dag, 40t/uke for 15-18 år.", "type": "yes_no_na", "prompt": "Er planlagt arbeidstid innenfor lovens grenser?", "law_ref": "AML §11-2", "required": true, "severity_default": "critical"}, {"key": "nattarbeid_unngas", "type": "yes_no_na", "prompt": "Er nattarbeid (kl 23-06) unngått eller særskilt unntatt?", "law_ref": "AML §11-3", "required": true, "severity_default": "critical"}, {"key": "helsekontroll", "type": "yes_no_na", "prompt": "Er helsekontroll gjennomført før arbeid?", "law_ref": "AML §11-4", "required": true, "severity_default": "high"}, {"key": "pauser_dokumentert", "type": "yes_no_na", "prompt": "Er pauseregler (30 min ved 4,5t) sikret i arbeidsplanen?", "law_ref": "AML §11-5", "required": true, "severity_default": "high"}, {"key": "foresatt_samtykke", "type": "yes_no_na", "prompt": "Er samtykke fra foresatt innhentet (under 18)?", "required": true, "severity_default": "critical"}, {"key": "signatur_naermeste_leder", "type": "signature", "prompt": "Nærmeste leders signatur", "required": true}, {"key": "signatur_foresatt", "type": "signature", "prompt": "Foresattes signatur (under 18)", "required": true}]}'::jsonb,
  true, 'ved tilsetting av mindreårig',
  '{"fields": []}'::jsonb,
  array['AML § 11-1', 'AML § 11-2', 'AML § 11-3', 'AML § 11-4', 'AML § 11-5']::text[],
  'draft', 'ansettelse'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'varsling-arsgjennomgang', 'Varsling — årsgjennomgang av rutiner og mottak', 'Årlig kontroll av at varslingsrutinene etter AML § 2A-7 er kjent, oppdaterte, og operative — at mottakskanalene fungerer, at habilitetskrav er ivaretatt, og at årsstatistikk er forsvarlig dokumentert.',
  '{"items": [{"key": "rutiner_skriftlige", "help": "Krav: rutinen ligger på intranett/HMS-håndbok, kjent ved onboarding, og oppdatert siste 12 mnd.", "type": "yes_no_na", "prompt": "Er varslingsrutinene skriftlige og lett tilgjengelige for alle ansatte?", "law_ref": "AML § 2A-7 (5)", "required": true, "severity_default": "critical"}, {"key": "rutiner_innhold", "type": "yes_no_na", "prompt": "Inneholder rutinen alle de fem lovpålagte minimumspunktene (oppfordring til å varsle, framgangsmåte, mottak, taushetsplikt, ekstern varsling)?", "law_ref": "AML § 2A-7 (5)", "required": true, "severity_default": "critical"}, {"key": "dom_drofting_amu", "help": "§ 2A-7 (4) krever drøfting før utarbeidelse/endring.", "type": "yes_no_na", "prompt": "Er rutinen drøftet med arbeidstakerne / tillitsvalgte og AMU?", "law_ref": "AML § 2A-7 (4)", "required": true, "severity_default": "high"}, {"key": "mottak_test", "help": "Send testvarsel og bekreft mottak innen 5 virkedager.", "type": "yes_no_na", "prompt": "Er e-post / portal / anonymt skjema testet siste 6 mnd. og fungerer?", "law_ref": "AML § 2A-3", "required": true, "severity_default": "high"}, {"key": "habilitet", "type": "yes_no_na", "prompt": "Er det fastsatt habilitetsregler for varslingsmottakerne (saksbehandler ≠ den det varsles om)?", "law_ref": "AML § 2A-3", "required": true, "severity_default": "high"}, {"key": "taushet", "type": "yes_no_na", "prompt": "Er taushetsplikten om varslerens identitet ivaretatt — gjelder også overfor sakens parter?", "law_ref": "AML § 2A-7 (3)", "required": true, "severity_default": "critical"}, {"key": "aktivitetsplikt", "type": "yes_no_na", "prompt": "Er aktivitetsplikten dokumentert for hvert varsel siste 12 mnd. (mottaksbekreftelse, undersøkelse, tilbakemelding)?", "law_ref": "AML § 2A-3", "required": true, "severity_default": "critical"}, {"key": "gjengjeldelsesvern", "type": "yes_no_na", "prompt": "Er det rutiner for å forebygge og avdekke gjengjeldelse mot varslere?", "law_ref": "AML § 2A-4", "required": true, "severity_default": "high"}, {"key": "statistikk", "type": "yes_no_na", "prompt": "Er avidentifisert årsstatistikk over varsler lagt fram for AMU?", "law_ref": "AML § 7-2 + § 2A-7", "required": true, "severity_default": "medium"}, {"key": "opplaering", "type": "yes_no_na", "prompt": "Har ledere og varslingsmottakere fått oppdatert opplæring siste 24 mnd.?", "law_ref": "AML § 3-2", "required": true, "severity_default": "medium"}, {"key": "arkivering", "type": "yes_no_na", "prompt": "Oppbevares varslingssaker i lukket arkiv i minst 5 år?", "law_ref": "AML § 2A-7 + GDPR Art. 5", "required": true, "severity_default": "medium"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner / forbedringspunkter", "required": false}, {"key": "sign_hms", "type": "signature", "prompt": "HMS-leders signatur", "required": true}, {"key": "sign_vo", "type": "signature", "prompt": "Verneombudets signatur", "required": true}]}'::jsonb,
  false, 'arlig',
  '{"fields": []}'::jsonb,
  array['AML § 2A-1', 'AML § 2A-2', 'AML § 2A-3', 'AML § 2A-4', 'AML § 2A-7']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'varsling-rutine-arssjekk', 'Varslingsrutine – årssjekk', 'Årlig kontroll av at virksomheten har skriftlig varslingsrutine og at den er kommunisert til alle ansatte (AML §2A-7). Obligatorisk for virksomheter med 5 eller flere ansatte.',
  '{"items": [{"key": "rutine_finnes", "type": "yes_no_na", "prompt": "Er skriftlig varslingsrutine utarbeidet?", "law_ref": "AML §2A-7", "required": true, "severity_default": "critical"}, {"key": "rutine_oppdatert", "type": "yes_no_na", "prompt": "Er rutinen oppdatert inneværende kalenderår?", "law_ref": "AML §2A-7", "required": true, "severity_default": "high"}, {"key": "rutine_kommunisert", "type": "yes_no_na", "prompt": "Er alle ansatte informert om varslingsrutinen og varslingskanalene?", "law_ref": "AML §2A-7", "required": true, "severity_default": "high"}, {"key": "mottaker_utpekt", "type": "yes_no_na", "prompt": "Er en ansvarlig mottaker (person/funksjon) av varsler utpekt og navngitt i rutinen?", "required": true, "severity_default": "high"}, {"key": "ekstern_kanal", "type": "yes_no_na", "prompt": "Er ekstern varslingsvei (Arbeidstilsynet, Økokrim, politi) beskrevet i rutinen?", "law_ref": "AML §2A-2", "required": true, "severity_default": "medium"}, {"key": "gjengjeldelse_forbud", "type": "yes_no_na", "prompt": "Er forbudet mot gjengjeldelse overfor varsler tydelig beskrevet i rutinen?", "law_ref": "AML §2A-3", "required": true, "severity_default": "high"}, {"key": "varsler_identitet", "type": "yes_no_na", "prompt": "Er vern av varslerens identitet og konfidensialitet beskrevet?", "law_ref": "AML §2A-4", "required": true, "severity_default": "medium"}, {"key": "siste_revisjonsdato", "type": "date", "prompt": "Dato for siste revisjon av rutinen", "law_ref": "AML §2A-7", "required": true}, {"key": "varsler_mottatt", "type": "yes_no_na", "prompt": "Er varsler mottatt og behandlet siste 12 måneder? (Ja = varsler mottatt, Nei = ingen)", "required": false}, {"key": "kommentar", "type": "text", "prompt": "Kommentarer eller forbedringspunkter til varslingsrutinen", "required": false}, {"key": "signatur_dagligleder", "type": "signature", "prompt": "Daglig leders signatur", "law_ref": "AML §2A-7", "required": true}]}'::jsonb,
  true, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 2A-1', 'AML § 2A-2', 'AML § 2A-3', 'AML § 2A-4', 'AML § 2A-7']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'verneombud-arsrapport', 'Verneombud-årsrapport', 'Årlig egenrapport fra verneombud om aktiviteter, samarbeid med AMU og egen opplæring (AML §6-2 + §6-5). Inngår som vedlegg til AMU-årsprotokoll.',
  '{"items": [{"key": "runder_gjennomfort", "type": "number", "prompt": "Antall vernerunder gjennomført dette året", "law_ref": "AML §6-2", "required": true}, {"key": "avvik_meldt", "type": "number", "prompt": "Antall avvik meldt fra verneombud", "law_ref": "AML §6-2", "required": true}, {"key": "samarbeid_amu", "type": "yes_no_na", "prompt": "Er saker brakt videre til AMU der det er aktuelt?", "law_ref": "AML §7-2", "required": false, "severity_default": "medium"}, {"key": "egen_opplaering", "type": "yes_no_na", "prompt": "Er verneombudets opplæring oppdatert?", "law_ref": "AML §6-5", "required": true, "severity_default": "high"}, {"key": "kommentar", "type": "text", "prompt": "Verneombudets kommentarer til arbeidsmiljøåret", "required": false}, {"key": "signatur_verneombud", "type": "signature", "prompt": "Verneombudets signatur", "law_ref": "AML §6-2", "required": true}, {"key": "signatur_dagligleder", "type": "signature", "prompt": "Daglig leders bekreftelse", "required": true}]}'::jsonb,
  true, 'årlig',
  '{"fields": []}'::jsonb,
  array['AML § 6-2', 'AML § 6-5', 'AML § 7-2']::text[],
  'draft', 'psykososialt'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'vernerunde-standard', 'Vernerunde – standard', 'Standard vernerunde etter arbeidsmiljøloven og internkontrollforskriften. ',
  '{"items": [{"key": "fysisk_arb_omr", "help": "Vurder belysning, støy, ergonomi, ryddighet.", "type": "yes_no_na", "prompt": "Er det fysiske arbeidsmiljøet forsvarlig?", "law_ref": "AML §4-1, §4-4", "required": true, "severity_default": "high"}, {"key": "verneutstyr_tilg", "type": "yes_no_na", "prompt": "Er nødvendig verneutstyr tilgjengelig og brukt?", "law_ref": "AML §3-2 (1)", "required": true, "severity_default": "critical"}, {"key": "psyk_arbmiljo", "type": "text", "prompt": "Er det forhold som påvirker psykososialt arbeidsmiljø negativt?", "law_ref": "AML §4-3", "required": false, "severity_default": "medium"}, {"key": "kjemikalier", "type": "yes_no_na", "prompt": "Er kjemikalier merket og oppbevart riktig?", "law_ref": "AML §4-5", "required": false, "severity_default": "high"}, {"key": "evakuering", "type": "yes_no_na", "prompt": "Er rømningsveier frie og merkede?", "law_ref": "Internkontrollforskriften §5", "required": true, "severity_default": "critical"}, {"key": "foto", "type": "photo", "prompt": "Bilder fra runden", "required": false}, {"key": "signatur_verneombud", "type": "signature", "prompt": "Verneombudets signatur", "law_ref": "AML §6-2", "required": true}]}'::jsonb,
  true, null,
  '{"fields": []}'::jsonb,
  array['AML § 3-2', 'AML § 4-1', 'AML § 4-3', 'AML § 4-4', 'AML § 4-5', 'AML § 6-2', 'IK-f § 5 nr. 7', 'IK-f § 5 nr. 8']::text[],
  'draft', 'vernerunder'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'aml-amu', 'virksomhetsoverdragelse-sjekk', 'Virksomhetsoverdragelse — gjennomføringssjekk', 'Sjekkliste til bruk ved konkret overdragelse — bekrefter at AML §§ 16-2 til 16-5 er ivaretatt før, under og etter transaksjonen.',
  '{"items": [{"key": "omfattes", "type": "yes_no_na", "prompt": "Er det avklart at transaksjonen omfattes av kap. 16 (selvstendig økonomisk enhet, identitet bevart)?", "law_ref": "AML § 16-1", "required": true, "severity_default": "critical"}, {"key": "tv_info", "type": "yes_no_na", "prompt": "Er tillitsvalgte informert så tidlig som mulig — om årsak, dato, konsekvenser og tiltak?", "law_ref": "AML § 16-5 (1)", "required": true, "severity_default": "critical"}, {"key": "tv_drofting", "type": "yes_no_na", "prompt": "Er det gjennomført drøftelse med tillitsvalgte før overdragelsen?", "law_ref": "AML § 16-5 (2)", "required": true, "severity_default": "critical"}, {"key": "arb_info", "type": "yes_no_na", "prompt": "Har hver enkelt arbeidstaker fått skriftlig informasjon om dato, rettsvirkninger og reservasjonsrett?", "law_ref": "AML § 16-5 (3)", "required": true, "severity_default": "critical"}, {"key": "reservasjonsfrist", "type": "yes_no_na", "prompt": "Er det fastsatt en rimelig reservasjonsfrist på minst 14 dager?", "law_ref": "AML § 16-3", "required": true, "severity_default": "high"}, {"key": "tariffavtale", "type": "yes_no_na", "prompt": "Er ny arbeidsgivers tariff-binding avklart (eller fristen for å erklære overfor fagforening notert)?", "law_ref": "AML § 16-2 (2)", "required": true, "severity_default": "high"}, {"key": "pensjon", "type": "yes_no_na", "prompt": "Er pensjonsordningen avklart — videreføres eller endres?", "law_ref": "AML § 16-2 (3)", "required": true, "severity_default": "high"}, {"key": "oppsigelser", "type": "yes_no_na", "prompt": "Er det bekreftet at ingen er sagt opp på grunn av selve overdragelsen?", "law_ref": "AML § 16-4", "required": true, "severity_default": "critical"}, {"key": "dokumenter_overlevert", "type": "yes_no_na", "prompt": "Er ansattlister, arbeidsavtaler og personalmapper overlevert ny arbeidsgiver i tråd med GDPR?", "law_ref": "GDPR Art. 6 + AML § 16-2", "required": true, "severity_default": "high"}, {"key": "reservasjoner", "type": "yes_no_na", "prompt": "Er reservasjoner registrert og håndtert?", "law_ref": "AML § 16-3", "required": true, "severity_default": "high"}, {"key": "kommentar", "type": "text", "prompt": "Observasjoner", "required": false}, {"key": "sign_overdrager", "type": "signature", "prompt": "Overdragers signatur", "required": true}, {"key": "sign_erverver", "type": "signature", "prompt": "Ny arbeidsgivers signatur", "required": false}]}'::jsonb,
  false, 'ad_hoc',
  '{"fields": []}'::jsonb,
  array['AML § 16-1', 'AML § 16-2', 'AML § 16-3', 'AML § 16-4', 'AML § 16-5']::text[],
  'draft', null
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
  review_status=excluded.review_status, category_slug=excluded.category_slug,
  updated_at=now();
insert into public.compliance_system_templates (pack, slug, name, description, definition, nav_pinned, cadence_hint, metadata_schema, law_refs, review_status, category_slug) values (
  'iso-45001', 'iso-45001-internal-audit', 'Internrevisjon – ISO 45001:2018', 'Internrevisjon mot ISO 45001 for arbeidsmiljøstyringssystem.',
  '{"items": [{"key": "context_4_1", "type": "yes_no_na", "prompt": "Er konteksten for OH&S-systemet vurdert og dokumentert?", "required": true, "iso_clause": "4.1", "severity_default": "medium"}, {"key": "leadership_5_1", "type": "yes_no_na", "prompt": "Demonstrerer toppledelsen lederskap og forpliktelse?", "required": true, "iso_clause": "5.1", "severity_default": "high"}, {"key": "policy_5_2", "type": "yes_no_na", "prompt": "Er HMS-policy etablert, kommunisert og tilgjengelig?", "required": true, "iso_clause": "5.2", "severity_default": "high"}, {"key": "consultation_5_4", "type": "text", "prompt": "Er ansattes konsultasjon og medvirkning sikret?", "required": true, "iso_clause": "5.4", "severity_default": "high"}, {"key": "risks_6_1", "type": "yes_no_na", "prompt": "Er risikoer og muligheter identifisert og håndtert?", "required": true, "iso_clause": "6.1.2", "severity_default": "critical"}, {"key": "legal_6_1_3", "type": "yes_no_na", "prompt": "Er lovkrav og andre krav identifisert og oppdatert?", "required": true, "iso_clause": "6.1.3", "severity_default": "high"}, {"key": "objectives_6_2", "type": "yes_no_na", "prompt": "Er HMS-mål etablert med tiltaksplan?", "required": true, "iso_clause": "6.2", "severity_default": "medium"}, {"key": "competence_7_2", "type": "yes_no_na", "prompt": "Er kompetansekrav definert og verifisert?", "required": true, "iso_clause": "7.2", "severity_default": "high"}, {"key": "operational_8_1", "type": "text", "prompt": "Er operativ planlegging og kontroll dokumentert?", "required": true, "iso_clause": "8.1", "severity_default": "high"}, {"key": "emergency_8_2", "type": "yes_no_na", "prompt": "Er beredskap for hendelser etablert og testet?", "required": true, "iso_clause": "8.2", "severity_default": "critical"}, {"key": "monitoring_9_1", "type": "yes_no_na", "prompt": "Er overvåking, måling og analyse av HMS-ytelse etablert?", "required": true, "iso_clause": "9.1", "severity_default": "high"}, {"key": "incident_10_2", "type": "yes_no_na", "prompt": "Er hendelser og avvik undersøkt med korrigerende tiltak?", "required": true, "iso_clause": "10.2", "severity_default": "critical"}, {"key": "improvement_10_3", "type": "text", "prompt": "Pågår kontinuerlig forbedring av systemet?", "required": true, "iso_clause": "10.3", "severity_default": "medium"}, {"key": "auditor_signature", "type": "signature", "prompt": "Revisors signatur", "required": true, "iso_clause": "9.2"}]}'::jsonb,
  true, null,
  '{"fields": []}'::jsonb,
  array['ISO 45001:2018 § 9.2']::text[],
  'draft', 'internrevisjon'
) on conflict (pack, slug) do update set
  name=excluded.name, description=excluded.description, definition=excluded.definition,
  nav_pinned=excluded.nav_pinned, cadence_hint=excluded.cadence_hint,
  metadata_schema=excluded.metadata_schema, law_refs=excluded.law_refs,
